module.exports = [
  // ── NP-007 … NP-052 ──────────────────────────────────────────────────────
  ['NP-007', 'ASSOCIATION', 'Diabetic & hypertensive kidney', 'New type 2 diabetic with BP 139/88 and microalbuminuria — best antihypertensive', 'Lisinopril', ['Amlodipine', 'Hydrochlorothiazide', 'Carvedilol'], ['Albumin in the urine that a dipstick misses (microalbuminuria) is the first sign of diabetic nephropathy.', 'ACE inhibitors such as lisinopril dilate the efferent arteriole, lowering glomerular pressure and slowing kidney damage.', 'An ARB is the alternative if an ACE inhibitor causes cough.']],
  ['NP-008', 'MECHANISM', 'Glomerular disease', 'Child with red urine and hypertension a month after a skin infection — cause of injury', 'IgG immune complexes', ['CD8⁺ T lymphocytes', 'IgG autoantibodies', 'Histamine release'], ['Red urine, swelling and high blood pressure weeks after a strep skin or throat infection is poststreptococcal glomerulonephritis.', 'Antibodies bind streptococcal antigens and the immune complexes lodge in the glomeruli, activating complement.', 'C3 is low, and the biopsy shows subepithelial "humps" on electron microscopy.']],
  ['NP-009', 'MECHANISM', 'Acid–base', 'Kidney excreting a large acid load — metabolism of which amino acid matters most?', 'Glutamine', ['Alanine', 'Arginine', 'Aspartate'], ['The proximal tubule breaks down glutamine to make ammonia, producing new bicarbonate at the same time.', 'Ammonia traps hydrogen ions in the urine as ammonium, which is the main way the kidney adapts to an acid load.', 'In metabolic acidosis the kidney sharply increases glutamine uptake and ammoniagenesis.']],
  ['NP-010', 'ASSOCIATION', 'Kidney stones', 'Staghorn stone filling the renal pelvis in a woman with recurrent UTIs — urinalysis', 'Urine pH 8.0', ['4+ protein', 'Red blood cell casts', 'Uric acid crystals'], ['Staghorn stones in recurrent infection are struvite stones (magnesium ammonium phosphate).', 'Urease-producing bacteria such as Proteus split urea into ammonia, which makes the urine alkaline.', 'Alkaline urine lets struvite precipitate, so the infection and the stone must both be removed.']],
  ['NP-011', 'ASSOCIATION', 'Diabetic & hypertensive kidney', 'Elderly man with CKD; biopsy shows thickened, narrowed arterioles and scarred glomeruli', 'Hypertension', ['Analgesic use', 'Multiple myeloma', 'Hepatitis C infection'], ['Long-standing high blood pressure thickens the walls of the small renal arteries (hyaline arteriolosclerosis).', 'Narrowed vessels starve the glomeruli, which scar over: hypertensive nephrosclerosis.', 'The kidneys become small with a finely granular surface.']],
  ['NP-012', 'ASSOCIATION', 'Congenital & developmental', 'Newborn with fatal lung failure, flat face and club feet; no prenatal care — autopsy finding', 'Renal agenesis', ['Diaphragmatic hernia', 'Duodenal atresia', 'Surfactant deficiency'], ['Without kidneys the fetus makes no urine, so amniotic fluid runs out (oligohydramnios).', 'Too little fluid compresses the fetus, causing a flat face, limb deformities and underdeveloped lungs: Potter sequence.', 'Pulmonary hypoplasia is what causes death soon after birth.']],
  ['NP-013', 'MECHANISM', 'Diabetic & hypertensive kidney', 'Newly diagnosed type 2 diabetes, no albuminuria yet — earliest kidney change', 'Higher glomerular filtration rate', ['Lower glomerular capillary pressure', 'Shrinking of the glomeruli', 'Lower peritubular oncotic pressure'], ['The earliest stage of diabetic nephropathy is hyperfiltration: GFR is higher than normal.', 'High glucose dilates the afferent arteriole and the efferent arteriole constricts, raising glomerular pressure.', 'Years of hyperfiltration lead to mesangial expansion, albuminuria and then falling GFR.']],
  ['NP-014', 'ASSOCIATION', 'Tubulointerstitial disease', 'Blood seen spurting from a ureteric orifice at cystoscopy — likely cause', 'Renal papillary necrosis', ['Urinary bladder cancer', 'Colovesical fistula', 'Urethral diverticulum'], ['Blood coming from a ureteric orifice means it is coming from the kidney or ureter, not the bladder.', 'Papillary necrosis kills the tips of the renal pyramids, which can slough off and bleed.', 'Causes include sickle cell disease or trait, diabetes, analgesic overuse and pyelonephritis.']],
  ['NP-015', 'MECHANISM', 'Water & sodium balance', 'Where does ADH increase urea reabsorption to build the medullary gradient?', 'Medullary collecting duct', ['Cortical collecting duct', 'Early distal tubule', 'Thin ascending limb'], ['ADH inserts urea transporters (UT-A1) in the inner medullary collecting duct.', 'Urea leaving the duct accumulates in the medulla and adds to the concentration gradient.', 'ADH also inserts aquaporin-2 water channels along the whole collecting duct.']],
  ['NP-016', 'ASSOCIATION', 'Acute kidney injury', 'Acute tubular necrosis now in the high-output recovery phase — main risk', 'Hypokalemia', ['Hyperphosphatemia', 'Volume overload', 'Urinary protein loss'], ['As damaged tubules recover, filtration returns before the tubules can reabsorb properly, so large volumes of urine pour out.', 'Potassium is lost in that dilute urine, so hypokalemia is the big risk.', 'Hyperkalemia and volume overload are the dangers of the earlier oliguric phase instead.']],
  ['NP-017', 'BUZZWORD', 'Glomerular disease', 'Nephrotic syndrome; biopsy shows Kimmelstiel–Wilson nodules', 'Diabetes mellitus', ['Hepatitis C infection', 'Systemic lupus erythematosus', 'HIV infection'], ['Kimmelstiel–Wilson nodules are round pink masses of mesangial matrix, the sign of nodular diabetic glomerulosclerosis.', 'Diabetic nephropathy is the most common cause of nephrotic syndrome in adults.', 'Other early changes are thickened basement membranes and hyaline arteriolosclerosis of both arterioles.']],
  ['NP-018', 'MECHANISM', 'Renal physiology', 'A second drug lowers the urinary excretion of a renally cleared drug — how?', 'Decreased tubular secretion', ['Increased glomerular filtration', 'Protein-binding displacement', 'Decreased tubular reabsorption'], ['Drugs leave the body in urine by filtration plus tubular secretion, minus reabsorption.', 'If two drugs share the same tubular transporter, one can block secretion of the other and lower its excretion.', 'A classic example is probenecid blocking the secretion of penicillin.']],
  ['NP-019', 'ASSOCIATION', 'Congenital & developmental', 'Horseshoe kidney — which structure stopped it rising?', 'Inferior mesenteric artery', ['Superior mesenteric artery', 'Inferior vena cava', 'Persistent urachus'], ['In a horseshoe kidney the lower poles are fused across the midline.', 'As the kidneys rise during development, the fused isthmus hooks under the inferior mesenteric artery and gets stuck.', 'It is linked to Turner syndrome and raises the risk of obstruction, infection and stones.']],
  ['NP-020', 'MECHANISM', 'Renovascular disease', 'Creatinine jumps after starting ramipril in an atherosclerotic man — which vessel is affected?', 'Efferent arteriole', ['Afferent arteriole', 'Collecting duct', 'Ascending limb of Henle'], ['With renal artery stenosis, angiotensin II constricts the efferent arteriole to keep glomerular pressure up.', 'ACE inhibitors remove that constriction, so the efferent arteriole dilates and filtration drops.', 'A big rise in creatinine after starting an ACE inhibitor suggests renal artery stenosis.']],
  ['NP-021', 'ASSOCIATION', 'Calcium & phosphate', 'Infused drug raises serum calcium and urinary phosphate in a dose-dependent way', 'Recombinant parathyroid hormone', ['1,25-dihydroxyvitamin D analog', 'FGF-23 inhibitor', 'RANK ligand inhibitor'], ['Parathyroid hormone raises blood calcium by acting on bone, kidney and, through vitamin D, the gut.', 'In the kidney it blocks phosphate reabsorption in the proximal tubule, so urine phosphate rises.', 'Teriparatide is recombinant PTH given intermittently to build bone in osteoporosis.']],
  ['NP-022', 'SIDE_EFFECT', 'Glomerular disease', 'Teenager with Wilson disease on penicillamine develops heavy proteinuria', 'Membranous nephropathy', ['Renal tubular injury', 'Interstitial nephritis', 'Medication noncompliance'], ['Penicillamine can trigger membranous nephropathy, causing nephrotic-range protein loss.', 'Membranous nephropathy shows thick capillary walls with subepithelial deposits ("spike and dome").', 'Other drug triggers include gold, NSAIDs and captopril.']],
  ['NP-023', 'MECHANISM', 'Acid–base', 'Toddler failing to thrive with glycosuria, low phosphate and normal anion gap acidosis — defect', 'Proximal tubule bicarbonate reabsorption', ['Proximal tubule H⁺ secretion', 'Distal tubule bicarbonate reabsorption', 'Distal tubule ammonia generation'], ['Glucose, phosphate and amino acids lost in the urine together point to a failing proximal tubule (Fanconi syndrome).', 'The proximal tubule normally reclaims most filtered bicarbonate, so its failure causes type 2 (proximal) renal tubular acidosis.', 'Causes include cystinosis in children and drugs such as tenofovir or ifosfamide.']],
  ['NP-024', 'ASSOCIATION', 'Acid–base', 'Confused man: pH 7.25, low PaCO₂, low bicarbonate, anion gap 34', 'Anion gap metabolic acidosis', ['Non-anion gap metabolic acidosis', 'Respiratory acidosis', 'Respiratory alkalosis'], ['A low pH with low bicarbonate is metabolic acidosis, and the low PaCO₂ is the lungs compensating.', 'An anion gap of 34 means an unmeasured acid has been added, such as ketones, lactate or a toxic alcohol.', 'Use MUDPILES to remember the causes of a high anion gap.']],
  ['NP-025', 'ASSOCIATION', 'Acid–base', 'Diabetic ketoacidosis — expected urine pH, bicarbonate and ammonium', 'Low pH, low HCO₃⁻, high NH₄⁺', ['High pH, low HCO₃⁻, high NH₄⁺', 'Low pH, low HCO₃⁻, low NH₄⁺', 'Low pH, high HCO₃⁻, high NH₄⁺'], ['In ketoacidosis the kidneys work to excrete the extra acid.', 'They reclaim all filtered bicarbonate, secrete hydrogen ions to acidify the urine, and make more ammonium.', 'Low urinary ammonium during an acidosis would suggest renal tubular acidosis instead.']],
  ['NP-026', 'MECHANISM', 'Water & sodium balance', 'No ADH at all — where is tubular fluid most concentrated?', 'Bottom of the loop of Henle', ['Proximal tubule', 'Thick ascending limb', 'Medullary collecting duct'], ['The descending limb loses water into the salty medulla, so fluid is most concentrated at the hairpin turn.', 'Without ADH the collecting duct stays impermeable to water, so the urine remains dilute.', 'With high ADH the medullary collecting duct would become the most concentrated site instead.']],
  ['NP-027', 'ASSOCIATION', 'Renal tumors', 'Smoker with polycythemia and round lung metastases made of clear cells — primary site', 'Kidney', ['Colon', 'Stomach', 'Testis'], ['Clear cell renal cell carcinoma is made of cells with clear cytoplasm full of lipid and glycogen.', 'It can secrete erythropoietin, which explains a raised hematocrit.', 'It often spreads by blood to the lungs, forming "cannonball" metastases; smoking is its main risk factor.']],
  ['NP-028', 'SIDE_EFFECT', 'Chronic kidney disease', 'CKD anemia treated with erythropoietin to a high hemoglobin — main risk', 'Venous thrombosis', ['Autoimmune hemolysis', 'Bone marrow fibrosis', 'Iron overload'], ['Erythropoietin raises red cell mass and blood viscosity, increasing clot risk.', 'Risks of thrombosis, stroke and high blood pressure rise when hemoglobin is pushed above about 11–12 g/dL.', 'Iron stores should be replete before starting it, because iron deficiency blunts the response.']],
  ['NP-029', 'BUZZWORD', 'Glomerular disease', 'Nephritic syndrome with linear IgG along the GBM — light microscopy', 'Crescent formation', ['Amyloid deposition', 'Nodular glomerulosclerosis', 'Normal glomeruli'], ['Linear IgG along the basement membrane is anti-GBM disease, caused by antibodies to type IV collagen.', 'It causes rapidly progressive glomerulonephritis, where cells and fibrin fill Bowman space as crescents.', 'When the lungs are also involved, with hemoptysis, it is called Goodpasture syndrome.']],
  ['NP-030', 'BUZZWORD', 'Cystic kidney disease', 'Flank pain, hematuria, hypertension, and cysts in both kidneys and the liver', 'Polycystic kidney disease', ['Glomerulonephritis', 'Hydronephrosis', 'Renal cell carcinoma'], ['Autosomal dominant polycystic kidney disease (PKD1 or PKD2) causes many enlarging cysts in both kidneys.', 'Liver cysts, berry aneurysms and mitral valve prolapse are associated findings.', 'Cyst bleeding or rupture causes flank pain and blood in the urine.']],
  ['NP-031', 'MECHANISM', 'Chronic kidney disease', 'CKD patient with carpal spasm when the BP cuff inflates — main contributor', 'High serum phosphate', ['Low parathyroid hormone', 'Low serum albumin', 'Vitamin D toxicity'], ['Failing kidneys cannot excrete phosphate, so it builds up.', 'Phosphate binds calcium and also blocks calcitriol production, so serum calcium falls.', 'Low calcium makes nerves irritable, causing carpal spasm when the cuff is inflated (Trousseau sign).']],
  ['NP-032', 'MECHANISM', 'Acute kidney injury', 'Earliest change in tubular cells during sublethal ischemia', 'Loss of epithelial cell polarity', ['Caspase activation', 'Basement membrane damage', 'Necrosis and sloughing'], ['Ischemia depletes ATP, and the actin cytoskeleton breaks down quickly without it.', 'Na⁺/K⁺-ATPase pumps then drift from the basolateral to the apical side, so the cell loses polarity.', 'Necrosis and sloughing come later, and only if the ischemia is severe or prolonged.']],
  ['NP-033', 'MECHANISM', 'Water & sodium balance', 'After 12 hours without water, tubular fluid of 110 mOsm/L was sampled where?', 'Distal convoluted tubule', ['Proximal convoluted tubule', 'Descending limb of Henle', 'Medullary collecting duct'], ['The thick ascending limb pumps out salt without water, so fluid entering the distal tubule is dilute.', 'The early distal tubule is the most dilute site in the nephron, whatever the ADH level.', 'With high ADH, water is then reabsorbed downstream in the collecting duct.']],
  ['NP-034', 'ASSOCIATION', 'Glomerular disease', 'Young woman with lupus features and nephrotic syndrome; thick capillary walls with spikes', 'Membranous nephropathy', ['Diffuse proliferative nephritis', 'Focal segmental glomerulosclerosis', 'Postinfectious glomerulonephritis'], ['Thick capillary walls without extra cells, with "spikes" on silver stain, is membranous nephropathy.', 'In lupus it is class V lupus nephritis, which presents as nephrotic syndrome.', 'Diffuse proliferative (class IV) lupus nephritis is the more common nephritic pattern.']],
  ['NP-035', 'MECHANISM', 'Water & sodium balance', 'Immediately after IV mannitol: serum sodium, filtrate osmolality, tubular flow', 'Sodium down, osmolality up, flow up', ['Sodium up, osmolality same, flow up', 'Sodium down, osmolality up, flow down', 'Sodium same, osmolality down, flow down'], ['Mannitol stays in the blood and draws water out of cells, which dilutes serum sodium at first.', 'It is freely filtered but not reabsorbed, so it raises the osmolality of the filtrate.', 'The trapped mannitol holds water in the tubule, so tubular flow and urine output rise.']],
  ['NP-036', 'ASSOCIATION', 'Renal tumors', 'Painless hematuria in an ex-smoker; renal mass with a chromosome 3p deletion — which gene?', 'VHL', ['WT1', 'RB', 'NF1'], ['Clear cell renal cell carcinoma is driven by loss of the VHL tumour suppressor gene on chromosome 3p.', 'Without VHL, HIF accumulates and switches on VEGF and erythropoietin.', 'Inherited von Hippel–Lindau disease also causes hemangioblastomas and pheochromocytomas.']],
  ['NP-037', 'ASSOCIATION', 'Renovascular disease', 'Bilateral renal artery stenosis started on lisinopril — expected kidney changes', 'Perfusion down, pressure down, FF down', ['Perfusion down, pressure up, FF down', 'Perfusion up, pressure down, FF down', 'Perfusion down, pressure down, FF same'], ['With narrowed renal arteries, the kidney depends on efferent constriction by angiotensin II to keep filtering.', 'An ACE inhibitor removes that constriction, so glomerular pressure and filtration fraction fall.', 'This can cause acute kidney injury, so creatinine must be checked soon after starting the drug.']],
  ['NP-038', 'ASSOCIATION', 'Renovascular disease', 'Young man with severe hypertension, low potassium, high renin and high aldosterone', 'Juxtaglomerular cell tumor', ['Adrenal cortical tumor', 'Adrenal medullary tumor', 'Pituitary tumor'], ['High renin with high aldosterone is secondary hyperaldosteronism, driven from the kidney.', 'In a young person with no renal artery narrowing, a renin-secreting juxtaglomerular tumour fits best.', 'An adrenal adenoma would instead give high aldosterone with low renin.']],
  ['NP-039', 'MECHANISM', 'Chronic kidney disease', 'How does sevelamer lower serum phosphorus in CKD?', 'Less intestinal phosphate absorption', ['Less proximal phosphate reabsorption', 'More FGF-23 release', 'Suppressed PTH secretion'], ['Sevelamer is a non-absorbed polymer that binds phosphate in the gut so it passes out in the stool.', 'It contains no calcium, so it does not add to vascular calcification.', 'Calcium acetate and lanthanum are other phosphate binders.']],
  ['NP-040', 'MECHANISM', 'Renal physiology', 'Which change lowers renal plasma flow but raises filtration fraction?', 'Efferent arteriole constriction', ['Afferent arteriole constriction', 'High plasma protein', 'Bladder neck obstruction'], ['Constricting the efferent arteriole backs pressure up into the glomerulus, so more plasma is filtered.', 'The same constriction adds resistance, so total renal plasma flow falls.', 'GFR rises relative to plasma flow, so the filtration fraction (GFR ÷ RPF) increases.']],
  ['NP-041', 'SIDE_EFFECT', 'Pharmacology', 'Three weeks after a new drug: potassium up from 4.8 to 5.2, creatinine up slightly', 'Lisinopril', ['Hydrochlorothiazide', 'Furosemide', 'Metformin'], ['ACE inhibitors dilate the efferent arteriole, which lowers GFR a little and raises creatinine.', 'They also lower aldosterone, so potassium rises.', 'A creatinine rise of up to about 30% is expected and acceptable; more suggests renal artery stenosis.']],
  ['NP-042', 'ASSOCIATION', 'Renal physiology', 'Healthy 62-year-old kidney donor — which age-related change matters?', 'Fewer functional glomeruli', ['Higher creatinine clearance', 'Higher renal blood flow', 'More sensitive renin release'], ['Normal ageing gradually reduces the number of working glomeruli, so GFR declines.', 'Creatinine may stay "normal" because older people also have less muscle.', 'Renal blood flow and renin responsiveness also fall with age.']],
  ['NP-043', 'MECHANISM', 'Kidney stones', 'High ileostomy output and a stone seen on ultrasound but not X-ray — mechanism', 'Concentrated, acidic urine', ['Ileal bile salt malabsorption', 'Urea-splitting bacteria', 'Excess parathyroid hormone'], ['Losing fluid and bicarbonate through an ileostomy leaves the urine both concentrated and acidic.', 'Uric acid crystallises in acidic urine, forming a stone that is invisible on plain X-ray.', 'Treatment is fluids and alkalinising the urine with potassium citrate.']],
  ['NP-044', 'ASSOCIATION', 'Congenital & developmental', 'Newborn with clear yellow fluid leaking from the umbilicus, worse when crying', 'Persistent allantois remnant', ['Patent vitelline duct', 'Absent neutrophil migration', 'Duplicated ureter'], ['The urachus is the remnant of the allantois connecting the bladder to the umbilicus.', 'If it stays open, urine leaks from the umbilicus, especially when crying raises abdominal pressure.', 'A patent vitelline (omphalomesenteric) duct instead leaks stool or meconium.']],
  ['NP-045', 'TRIAD', 'Glomerular disease', 'Child with nephrotic syndrome after a bee sting — LM, IF and EM findings', 'Normal LM, negative IF, effaced podocytes', ['Crescents, linear IgG, no deposits', 'Mesangial cells, IgA, mesangial deposits', 'Thick walls, granular IgG, subepithelial deposits'], ['Minimal change disease is the most common cause of nephrotic syndrome in children and can follow allergies or infections.', 'Light microscopy and immunofluorescence look normal; only electron microscopy shows flattened podocyte foot processes.', 'It responds very well to corticosteroids.']],
  ['NP-046', 'ASSOCIATION', 'Calcium & phosphate', 'Recurrent calcium stones, aches, ulcers, high calcium, low phosphate — bone change', 'Subperiosteal resorption', ['Mosaic lamellar bone', 'Osteoid around trabeculae', 'Marrow filled by spongiosa'], ['High calcium with low phosphate and calcium stones is primary hyperparathyroidism, usually from an adenoma.', 'Excess PTH activates osteoclasts, which resorb bone beneath the periosteum, typically on the middle phalanges.', 'Severe disease causes osteitis fibrosa cystica with "brown tumours".']],
  ['NP-047', 'MECHANISM', 'Glomerular disease', 'Child with palpable purpura on buttocks, joint pain and hematuria after a cold — mechanism', 'Mesangial immune complex deposition', ['Antibodies to podocyte antigens', 'Antibodies to basement membrane', 'Glomerular capillary thrombosis'], ['This is IgA vasculitis (Henoch–Schönlein purpura), the most common childhood vasculitis.', 'IgA immune complexes deposit in small vessels and in the glomerular mesangium.', 'It also causes abdominal pain and can lead to intussusception.']],
  ['NP-048', 'ASSOCIATION', 'Obstruction & urinary tract', 'Pelvic cancer surgery, then a swollen kidney on that side — explanation', 'Hydronephrosis', ['Renal vein thrombosis', 'Interstitial nephritis', 'Vesicoureteral reflux'], ['The ureter passes under the uterine artery ("water under the bridge"), where it can be tied off during hysterectomy.', 'A blocked ureter backs urine up, dilating the renal pelvis and calyces.', 'Unrelieved obstruction thins the cortex and can destroy the kidney.']],
  ['NP-049', 'ASSOCIATION', 'Water & sodium balance', 'Smoker with lung cancer and hyponatremia — serum osm, urine osm, urine sodium', 'Serum low, urine high, Na⁺ high', ['Serum high, urine high, Na⁺ normal', 'Serum low, urine high, Na⁺ low', 'Serum low, urine low, Na⁺ low'], ['Small cell lung cancer can secrete ADH, causing the syndrome of inappropriate ADH (SIADH).', 'Water is retained, so serum osmolality falls while the urine stays inappropriately concentrated.', 'The body is not salt-depleted, so urine sodium stays high; treat with fluid restriction.']],
  ['NP-050', 'ASSOCIATION', 'Obstruction & urinary tract', 'Woman with four vaginal births leaks urine when coughing or sneezing — cause', 'Urethral sphincter dysfunction', ['Detrusor overactivity', 'Bladder outlet obstruction', 'Neurogenic bladder'], ['Leakage when abdominal pressure rises is stress incontinence.', 'Childbirth weakens the pelvic floor and urethral sphincter, so they cannot hold against the pressure.', 'Treatment is pelvic floor (Kegel) exercises, then a sling operation if needed.']],
  ['NP-051', 'ASSOCIATION', 'Congenital & developmental', 'Oligohydramnios causing flat face, limb deformities and lung hypoplasia — best classification', 'Sequence', ['Association', 'Dysplasia', 'Polymorphism'], ['A sequence is a cascade of problems that all follow from one initial defect.', 'In Potter sequence the first problem is too little amniotic fluid, which compresses the fetus and limits lung growth.', 'An association is a group of defects that occur together more often than chance, without one single cause.']],
  ['NP-052', 'BUZZWORD', 'Glomerular disease', 'Electron microscopy humps in a child with nephritis after a skin infection', 'Immune complex deposits', ['Fibrin deposition', 'Hyaline material', 'Albumin buildup'], ['Poststreptococcal glomerulonephritis shows large subepithelial immune complex deposits, seen as "humps".', 'Immunofluorescence shows a granular "starry sky" pattern of IgG and C3.', 'Most children recover fully, but some adults go on to chronic kidney disease.']],

  // ── NP-053 … NP-098 ──────────────────────────────────────────────────────
  ['NP-053', 'ASSOCIATION', 'Acid–base', 'Diabetic man: Na 138, Cl 110, HCO₃⁻ 18 — likely diagnosis', 'Renal tubular acidosis', ['Diabetic ketoacidosis', 'Lactic acidosis', 'Primary hyperaldosteronism'], ['The anion gap is 138 − (110 + 18) = 10, which is normal, so this is a non-anion gap metabolic acidosis.', 'The main causes are diarrhoea and renal tubular acidosis; in diabetes, type 4 RTA from low aldosterone is common.', 'Ketoacidosis and lactic acidosis both raise the anion gap.']],
  ['NP-054', 'ASSOCIATION', 'Acute kidney injury', 'Creatinine rises 3 days after cardiac catheterization with contrast — kidney change', 'Proximal tubular cell necrosis', ['Glomerular crescents', 'Interstitial mononuclear cells', 'Fibrinoid arteriolar walls'], ['Iodinated contrast constricts renal vessels and is directly toxic to tubular cells, causing acute tubular necrosis.', 'Creatinine typically rises 1–3 days after the dose and recovers within a week or two.', 'Prevention is IV fluids and using as little contrast as possible in high-risk patients.']],
  ['NP-055', 'MECHANISM', 'Acute kidney injury', 'Heart failure patient\'s creatinine rises after starting ibuprofen — mechanism', 'Impaired afferent vasodilation', ['Impaired efferent vasodilation', 'Renal interstitial inflammation', 'Toxic proximal tubule injury'], ['When renal blood flow is low, as in heart failure, prostaglandins keep the afferent arteriole dilated.', 'NSAIDs block prostaglandin synthesis, so the afferent arteriole constricts and GFR falls.', 'The injury is hemodynamic and usually reverses when the NSAID is stopped.']],
  ['NP-056', 'ASSOCIATION', 'Obstruction & urinary tract', 'Suprapubic catheter for urinary retention — layer crossed besides the bladder wall', 'Anterior abdominal aponeurosis', ['Parietal peritoneum', 'Visceral peritoneum', 'Perineal membrane'], ['The bladder lies outside the peritoneal cavity, below and in front of the peritoneum.', 'A full bladder pushes the peritoneum upward, so a needle just above the pubis passes through the abdominal wall straight into the bladder.', 'The peritoneum is not crossed, which avoids injuring the bowel.']],
  ['NP-057', 'ASSOCIATION', 'Renal tumors', 'Kidney mass with lytic spinal metastases — which risk factor contributed?', 'Smoking', ['Alcohol use', 'Family history', 'Diet'], ['A kidney mass with lytic bone lesions suggests metastatic renal cell carcinoma.', 'Smoking is the most important modifiable risk factor for renal cell carcinoma.', 'Obesity, hypertension and long-term dialysis are other risk factors.']],
  ['NP-058', 'ASSOCIATION', 'Water & sodium balance', 'Polyuria with low sodium; urine concentrates with water deprivation, no change with ADH — treatment', 'Water restriction', ['Desmopressin', 'Hydrochlorothiazide', 'Indomethacin'], ['Low sodium with dilute urine that concentrates normally when water is withheld is primary (psychogenic) polydipsia.', 'The kidneys and ADH work fine; the person is simply drinking too much water.', 'Diabetes insipidus would instead cause high sodium and failure to concentrate the urine.']],
  ['NP-059', 'SIDE_EFFECT', 'Pharmacology', 'Elderly woman with CKD loses her hearing after a week of IV diuretics for heart failure', 'Furosemide', ['Hydrochlorothiazide', 'Spironolactone', 'Digoxin'], ['Loop diuretics can damage the inner ear, especially at high IV doses.', 'Kidney disease raises the risk because the drug accumulates.', 'Using them together with aminoglycosides adds to the ototoxicity.']],
  ['NP-060', 'ASSOCIATION', 'Chronic kidney disease', 'Advanced CKD: PTH, calcium, phosphate, 25-OH vitamin D, 1,25-(OH)₂ vitamin D', 'High, low, high, normal, low', ['High, high, low, normal, high', 'Low, low, high, normal, low', 'High, low, low, low, low'], ['Failing kidneys retain phosphate and cannot make 1,25-dihydroxyvitamin D.', 'Calcium falls, and both low calcium and high phosphate drive the parathyroids to make more PTH.', 'This is secondary hyperparathyroidism, which leads to renal osteodystrophy.']],
  ['NP-061', 'BUZZWORD', 'Glomerular disease', 'Young adult with recurrent gross hematuria, red cell casts and normal complement', 'IgA nephropathy', ['Membranous nephropathy', 'Minimal change disease', 'Poststreptococcal glomerulonephritis'], ['IgA nephropathy is the most common glomerulonephritis worldwide.', 'Visible blood in the urine often appears within a day or two of a mucosal infection.', 'Complement is normal, unlike poststreptococcal glomerulonephritis, which comes weeks later with low C3.']],
  ['NP-062', 'MECHANISM', 'Renal physiology', 'Decompensated heart failure — what is the kidney doing?', 'More proximal sodium reabsorption', ['Less distal sodium reabsorption', 'More free water excretion', 'Higher renal blood flow'], ['Low cardiac output reduces kidney perfusion, which activates the renin–angiotensin–aldosterone system.', 'Angiotensin II directly increases sodium reabsorption in the proximal tubule.', 'Aldosterone and ADH then retain more salt and water, worsening the congestion.']],
  ['NP-063', 'ASSOCIATION', 'Calcium & phosphate', 'Rickets with alopecia in a toddler — calcium, phosphate, 25-OH D, 1,25-(OH)₂ D', 'Low, low, normal, high', ['Low, low, low, low', 'Low, low, low, normal', 'High, low, normal, high'], ['Rickets with hair loss suggests hereditary vitamin D–resistant rickets, where the vitamin D receptor does not work.', 'The body senses low calcium and raises PTH, which pushes 1,25-dihydroxyvitamin D very high.', 'Nutritional vitamin D deficiency would instead show a low 25-hydroxyvitamin D.']],
  ['NP-064', 'MECHANISM', 'Glomerular disease', 'Frothy urine and pitting ankle swelling — which force is decreased?', 'Plasma oncotic pressure', ['Capillary hydrostatic pressure', 'Interstitial fluid pressure', 'Circulating aldosterone'], ['Frothy urine means heavy protein loss, so serum albumin falls in nephrotic syndrome.', 'Albumin provides most of the oncotic pressure that holds fluid inside vessels.', 'With less oncotic pull, fluid leaks into the tissues and causes edema.']],
  ['NP-065', 'ASSOCIATION', 'Diabetic & hypertensive kidney', 'Autopsy shows onion-skin thickening of renal arterioles — what would have prevented it?', 'Antihypertensives', ['Antiplatelet agents', 'Glucocorticoids', 'Hypoglycemic agents'], ['Concentric "onion-skin" layering of arteriole walls is hyperplastic arteriolosclerosis.', 'It is the hallmark of malignant hypertension, often with fibrinoid necrosis.', 'Controlling blood pressure prevents it, and kidney damage can be dramatic.']],
  ['NP-066', 'MECHANISM', 'Chronic kidney disease', 'Hemodialysis for lithium toxicity — which change speeds lithium removal?', 'Larger membrane surface area', ['Smaller membrane pores', 'Thicker membrane', 'Cooler dialysis solution'], ['Dialysis removes solutes by diffusion across a membrane.', 'By Fick\'s law, diffusion rises with surface area and concentration gradient and falls with membrane thickness.', 'Lithium is small and not protein-bound, so it is cleared well by dialysis.']],
  ['NP-067', 'SIDE_EFFECT', 'Pharmacology', 'Head injury treated with IV mannitol, then sudden breathlessness and crackles — cause', 'Rapid rise in blood volume', ['Excess ADH release', 'IgE-mediated drug reaction', 'Direct lung toxicity'], ['Mannitol draws water out of cells and into the bloodstream before the kidneys can excrete it.', 'In someone with a weak heart, that sudden extra volume floods the lungs (pulmonary edema).', 'Mannitol is avoided in heart failure and anuria for this reason.']],
  ['NP-068', 'MECHANISM', 'Renal physiology', 'High potassium intake: % of filtered K⁺ left at Bowman space, end-PCT, early DCT, urine', '100%, 35%, 10%, 110%', ['100%, 35%, 70%, 110%', '75%, 50%, 25%, 110%', '100%, 50%, 100%, 110%'], ['The proximal tubule reabsorbs about 65% of filtered potassium and the loop takes most of the rest.', 'The distal nephron and collecting duct then adjust potassium by secreting it.', 'With a high intake, secretion can push urine potassium above the filtered load.']],
  ['NP-069', 'ASSOCIATION', 'Kidney stones', 'Teenager with recurrent stones and hexagonal crystals — further testing shows', 'Aminoaciduria', ['Hypercalciuria', 'Hyperoxaluria', 'Hyperuricosuria'], ['Hexagonal crystals are cystine, and recurrent stones in a young person suggest cystinuria.', 'A defect in the transporter for cystine, ornithine, lysine and arginine (COLA) lets these amino acids spill into urine.', 'The urine cyanide–nitroprusside test is positive; treatment is fluids and alkalinising the urine.']],
  ['NP-070', 'ASSOCIATION', 'Pharmacology', 'Acute decompensated heart failure — brisk diuresis drug acts where?', 'Thick ascending limb of Henle', ['Proximal convoluted tubule', 'Distal convoluted tubule', 'Collecting duct'], ['Loop diuretics such as furosemide block the Na⁺/K⁺/2Cl⁻ cotransporter in the thick ascending limb.', 'That segment reabsorbs about a quarter of filtered sodium, so loop diuretics are the most powerful.', 'Side effects include low potassium, low magnesium, ototoxicity and hypocalcemia.']],
  ['NP-071', 'SIDE_EFFECT', 'Pharmacology', 'A higher diuretic dose raises serum calcium — where does it act?', 'Distal convoluted tubule', ['Thick ascending limb of Henle', 'Proximal convoluted tubule', 'Collecting duct'], ['Thiazides block the Na⁺/Cl⁻ cotransporter in the distal convoluted tubule.', 'This increases calcium reabsorption there, so serum calcium rises and urine calcium falls.', 'That is why thiazides are used to prevent calcium kidney stones.']],
  ['NP-072', 'MECHANISM', 'Obstruction & urinary tract', 'Urge incontinence — treatment drug effect', 'Muscarinic receptor antagonism', ['Alpha-1 receptor antagonism', 'Beta-1 receptor antagonism', 'Nicotinic receptor antagonism'], ['Urge incontinence comes from an overactive detrusor muscle contracting before the bladder is full.', 'Detrusor contraction is driven by acetylcholine on M3 receptors.', 'Antimuscarinics such as oxybutynin relax it; mirabegron, a β3 agonist, is an alternative.']],
  ['NP-073', 'ASSOCIATION', 'Calcium & phosphate', 'Celiac disease with bone pain — calcium, phosphate, PTH', 'Low, low, high', ['High, low, high', 'Low, high, high', 'Normal, high, high'], ['Celiac disease damages the small intestine, so vitamin D and calcium are poorly absorbed.', 'Low calcium raises PTH (secondary hyperparathyroidism), and PTH makes the kidney waste phosphate.', 'The result is osteomalacia, with bone pain and weakness.']],
  ['NP-074', 'ASSOCIATION', 'Acute kidney injury', 'Poor intake after pyelonephritis; BUN:Cr > 20, low urine sodium, bland urine', 'Prerenal azotemia', ['Acute tubular necrosis', 'Interstitial nephritis', 'Urinary tract obstruction'], ['Not drinking enough leaves the kidneys under-perfused, so they hold on to sodium and water.', 'A BUN-to-creatinine ratio above 20, urine sodium below 20 and a FENa below 1% point to a prerenal cause.', 'In acute tubular necrosis the tubules cannot hold sodium, so urine sodium is high and muddy brown casts appear.']],
  ['NP-075', 'ASSOCIATION', 'Renal physiology', 'Same creatinine, very different eGFRs in two healthy volunteers — why?', 'Skeletal muscle mass', ['Basal metabolic rate', 'Dietary purine intake', 'Hepatic synthetic function'], ['Creatinine is made by muscle at a fairly steady rate.', 'Someone with more muscle makes more creatinine, so the same serum level means a higher GFR.', 'eGFR equations adjust for age and sex partly to account for differences in muscle mass.']],
  ['NP-076', 'ASSOCIATION', 'Acute kidney injury', 'After prolonged seizures: dark urine, dipstick blood 3+ but no red cells on microscopy', 'Myoglobin tubular injury', ['Hemoglobin tubular injury', 'Light chain deposition', 'Immune complex injury'], ['Prolonged seizures break down muscle (rhabdomyolysis), releasing myoglobin.', 'Myoglobin turns the dipstick positive for blood even though no red cells are seen.', 'It is toxic to the tubules and blocks them with casts; treat with aggressive IV fluids.']],
  ['NP-077', 'ASSOCIATION', 'Acid–base', 'After large-volume normal saline: pH, bicarbonate, chloride, urine sodium', 'Down, down, up, up', ['Down, down, down, down', 'Up, up, down, up', 'Up, up, down, unchanged'], ['Normal saline contains far more chloride than plasma, so large volumes raise serum chloride.', 'The extra chloride lowers bicarbonate, causing a hyperchloremic, non-anion gap metabolic acidosis.', 'The kidneys excrete the extra sodium load, so urine sodium rises.']],
  ['NP-078', 'BUZZWORD', 'Glomerular disease', 'Dark urine and hypertension a month after facial impetigo — glomerular change', 'Subepithelial humps on EM', ['Linear IgG on IF', 'Basement membrane splitting', 'Diffuse wall thickening'], ['Nephritis weeks after impetigo or strep throat is poststreptococcal glomerulonephritis.', 'Electron microscopy shows subepithelial immune complex humps, and light microscopy shows swollen, cell-packed glomeruli.', 'C3 is low and anti-streptococcal antibodies such as anti-DNase B are positive.']],
  ['NP-079', 'ASSOCIATION', 'Chronic kidney disease', 'Dialysis patient with extensive vascular calcification on imaging — contributor', 'Hyperphosphatemia', ['Hypermagnesemia', 'Hypophosphatemia', 'Recurrent hypoglycemia'], ['In kidney failure phosphate builds up and combines with calcium in vessel walls.', 'High phosphate also turns vascular smooth muscle cells into bone-like cells that lay down calcium.', 'Vascular calcification is a major reason dialysis patients have high cardiovascular risk.']],
  ['NP-080', 'ASSOCIATION', 'Obstruction & urinary tract', 'Fetal hydronephrosis on one side with a normal ureter — where is the obstruction?', 'Ureteropelvic junction', ['Vesicoureteral junction', 'Urethra', 'Spinal cord'], ['A dilated renal pelvis with a normal-calibre ureter puts the block where the pelvis meets the ureter.', 'Ureteropelvic junction obstruction is the most common cause of hydronephrosis in fetuses and infants.', 'It comes from incomplete recanalisation of the ureter or a crossing vessel.']],
  ['NP-081', 'BUZZWORD', 'Glomerular disease', 'Rapidly progressive GN — what fills the crescent in Bowman space?', 'Fibrin', ['Amyloid', 'IgE', 'Lipid'], ['Crescents form when glomerular capillaries rupture and fibrin leaks into Bowman space.', 'Fibrin stimulates parietal epithelial cells and macrophages to proliferate, forming the crescent.', 'Crescents define rapidly progressive glomerulonephritis, which can destroy kidney function within weeks.']],
  ['NP-082', 'ASSOCIATION', 'Renal physiology', 'Normal pregnancy: renal blood flow, GFR and serum creatinine', 'Increased, increased, decreased', ['Decreased, decreased, unchanged', 'Decreased, unchanged, decreased', 'Unchanged, increased, increased'], ['Pregnancy expands blood volume and dilates the renal vessels, so renal blood flow and GFR rise by about 50%.', 'Higher GFR clears more creatinine, so serum creatinine falls below non-pregnant levels.', 'A "normal" creatinine of 1.0 mg/dL can therefore mean kidney dysfunction in pregnancy.']],
  ['NP-083', 'ASSOCIATION', 'Renal tumors', 'Smoker with a left flank mass, swelling of both legs and dilated abdominal wall veins', 'Inferior vena cava', ['Femoral veins', 'Portal vein', 'Saphenous veins'], ['Renal cell carcinoma tends to grow into the renal vein and can extend up the inferior vena cava.', 'Blocking the IVC causes swelling of both legs and collateral veins across the abdominal wall.', 'A left-sided tumour can also block the left testicular vein and cause a left varicocele.']],
  ['NP-084', 'MECHANISM', 'Renal tumors', 'Smoker with a flank mass and hematuria; high hemoglobin, normal WBC and platelets', 'Excess erythropoietin production', ['Myeloproliferative disorder', 'Extramedullary hematopoiesis', 'Reduced plasma volume'], ['Renal cell carcinoma can secrete erythropoietin, which raises only the red cell count.', 'A myeloproliferative disorder like polycythemia vera would usually raise white cells and platelets too.', 'Other paraneoplastic effects of RCC include high calcium (PTHrP) and high blood pressure (renin).']],
  ['NP-085', 'ASSOCIATION', 'Renal tumors', 'Bladder cancer in a heavy smoker — feature that most suggests a poor prognosis', 'Muscularis propria invasion', ['High-grade intraepithelial lesion', 'Papillary tumor shape', 'Tumor larger than 2 cm'], ['How deep the tumour invades (its stage) is the most important prognostic factor in bladder cancer.', 'Once it reaches the muscle layer, it can spread to lymph nodes and usually needs cystectomy.', 'Smoking is the strongest risk factor for urothelial carcinoma.']],
  ['NP-086', 'ASSOCIATION', 'Congenital & developmental', 'Horseshoe kidney on CT — which embryologic structure fused?', 'Metanephros', ['Mesonephros', 'Pronephros', 'Mesonephric duct'], ['The permanent kidney develops from the metanephros, formed by the ureteric bud and the metanephric blastema.', 'In a horseshoe kidney the two metanephric masses fuse at their lower poles.', 'The pronephros and mesonephros are temporary kidneys that disappear or become other structures.']],
  ['NP-087', 'ASSOCIATION', 'Kidney stones', 'Child with poor gut absorption of cystine, ornithine, lysine and arginine — main risk', 'Kidney stones', ['Aortic dissection', 'Intellectual disability', 'Rickets'], ['Cystinuria affects the same transporter in the gut and in the proximal tubule.', 'The kidney cannot reclaim cystine, which is poorly soluble and forms stones.', 'Patients are not malnourished, because the amino acids can still be absorbed as small peptides.']],
  ['NP-088', 'ASSOCIATION', 'Congenital & developmental', 'Which adult structure develops from the metanephric blastema?', 'Distal convoluted tubules', ['Collecting ducts', 'Minor calyces', 'Renal pelvis'], ['The metanephric blastema forms the nephron, from the glomerulus through the distal convoluted tubule.', 'The ureteric bud forms the collecting system: collecting ducts, calyces, pelvis and ureter.', 'Each tissue needs signals from the other, so loss of either causes renal agenesis.']],
  ['NP-089', 'ASSOCIATION', 'Kidney stones', 'Recurrent colicky pain with hematuria; high calcium, low phosphate', 'Ureterolithiasis', ['Renal infarction', 'Renal cell carcinoma', 'Ovarian torsion'], ['Sudden colicky flank pain with blood in the urine is a stone passing down the ureter.', 'High calcium with low phosphate suggests primary hyperparathyroidism, which causes calcium stones.', 'Most stones are calcium oxalate and show up on CT and usually on X-ray.']],
  ['NP-090', 'MECHANISM', 'Calcium & phosphate', 'High calcium and low phosphate with normal creatinine — mechanism of the low phosphate', 'Less proximal tubule reabsorption', ['More bone phosphate deposition', 'More fecal phosphate loss', 'Shift of phosphate into cells'], ['This is primary hyperparathyroidism, and PTH removes phosphate transporters from the proximal tubule.', 'Less phosphate is reclaimed, so it is lost in the urine and serum phosphate falls.', 'PTH raises calcium by increasing bone resorption, distal calcium reabsorption and calcitriol production.']],
  ['NP-091', 'MECHANISM', 'Renal physiology', 'Proximal tubule TF/P curves: line rising slowly vs line falling — which substances?', 'Urea, bicarbonate', ['Bicarbonate, sodium', 'Creatinine, glucose', 'Potassium, chloride'], ['As water is reabsorbed, a poorly reabsorbed solute like urea becomes slightly more concentrated.', 'Bicarbonate is reabsorbed faster than water early in the proximal tubule, so its ratio falls.', 'Creatinine rises the most steeply, because it is not reabsorbed at all.']],
  ['NP-092', 'SIDE_EFFECT', 'Water & sodium balance', 'Euvolemic hyponatremia with concentrated urine in a woman on seizure medication', 'Carbamazepine', ['Lithium', 'Furosemide', 'Spironolactone'], ['Carbamazepine causes SIADH by increasing ADH release and the kidney\'s response to it.', 'SIADH gives low serum osmolality, inappropriately concentrated urine and normal volume status.', 'Lithium does the opposite: it causes nephrogenic diabetes insipidus.']],
  ['NP-093', 'ASSOCIATION', 'Obstruction & urinary tract', 'Infant with febrile UTI and vesicoureteral reflux that resolves a year later — cause', 'Short intravesical ureter', ['Posterior urethral valve', 'Obstructing renal stone', 'Rectovaginal septum damage'], ['The ureter normally runs obliquely through the bladder wall, which closes it like a valve when the bladder contracts.', 'If that tunnel is too short, urine flows back up the ureter: primary vesicoureteral reflux.', 'As the child grows the tunnel lengthens, so mild reflux often resolves on its own.']],
  ['NP-094', 'ASSOCIATION', 'Obstruction & urinary tract', 'Pelvic floor exercises for stress incontinence target which structure?', 'Levator ani muscle complex', ['Detrusor muscle', 'Internal urethral sphincter', 'Uterosacral ligament'], ['The levator ani forms the pelvic floor that supports the bladder neck and urethra.', 'Strengthening it helps keep the urethra closed when coughing or sneezing raises abdominal pressure.', 'The detrusor is the bladder wall muscle, which is the target in urge incontinence instead.']],
  ['NP-095', 'ASSOCIATION', 'Water & sodium balance', 'Infant with polyuria, high sodium, X-linked family history — serum osm, deprivation, desmopressin', 'High, low, no change', ['High, low, increased', 'Normal, high, no change', 'Low, low, increased'], ['Congenital nephrogenic diabetes insipidus is most often from an X-linked V2 receptor mutation.', 'The kidney cannot respond to ADH, so urine stays dilute even with water deprivation and after desmopressin.', 'Losing free water raises serum sodium and osmolality; thiazides and a low-salt diet help.']],
  ['NP-096', 'ASSOCIATION', 'Pharmacology', 'Urinary retention after spinal anesthesia from a weak detrusor — helpful drug', 'Bethanechol', ['Oxybutynin', 'Finasteride', 'Phenylephrine'], ['Bethanechol is a muscarinic agonist that stimulates the detrusor muscle to contract.', 'It is not broken down by cholinesterase, so its effect lasts.', 'It must not be used when retention is caused by a mechanical obstruction.']],
  ['NP-097', 'BUZZWORD', 'Glomerular disease', 'Boy with brown urine, periorbital edema and hypertension; red cell casts, normal CK', 'Postinfectious glomerulonephritis', ['Minimal change disease', 'Rhabdomyolysis', 'Pyelonephritis'], ['Brown urine with red cell casts, edema and high blood pressure is a nephritic syndrome.', 'In a child this is most often postinfectious (poststreptococcal) glomerulonephritis.', 'A normal creatine kinase rules out rhabdomyolysis as the cause of the dark urine.']],
  ['NP-098', 'BUZZWORD', 'Glomerular disease', 'Adult nephrotic syndrome with anti-phospholipase A2 receptor antibodies', 'Membranous nephropathy', ['Focal segmental glomerulosclerosis', 'Minimal change disease', 'Multiple myeloma'], ['Anti-PLA2R antibodies are found in most cases of primary membranous nephropathy.', 'The antibodies target podocytes and form subepithelial deposits ("spike and dome").', 'Membranous nephropathy raises the risk of blood clots, especially renal vein thrombosis.']],

  // ── NP-099 … NP-144 ──────────────────────────────────────────────────────
  ['NP-099', 'MECHANISM', 'Obstruction & urinary tract', 'Cervical cancer partly blocking the right ureter — right kidney GFR and filtration fraction', 'Decreased, decreased', ['Decreased, increased', 'No change, increased', 'Decreased, no change'], ['A blocked ureter backs urine up and raises hydrostatic pressure in Bowman space.', 'That pressure opposes filtration, so GFR falls while plasma flow changes less.', 'With GFR falling more than plasma flow, the filtration fraction falls too.']],
  ['NP-100', 'ASSOCIATION', 'Renal physiology', 'Compared with measured creatinine clearance, the true GFR is about…', '20% lower', ['20% higher', 'Equal', '90% lower'], ['Creatinine is filtered and also slightly secreted by the proximal tubule.', 'That extra secreted creatinine makes creatinine clearance overestimate GFR by about 10–20%.', 'Inulin is filtered but neither secreted nor reabsorbed, so its clearance equals GFR exactly.']],
  ['NP-101', 'ASSOCIATION', 'Pharmacology', 'Elderly woman with urge incontinence and memory problems — best drug effect', 'Beta-3 receptor stimulation', ['Muscarinic receptor stimulation', 'Alpha-1 receptor antagonism', 'Nicotinic receptor antagonism'], ['Mirabegron stimulates β3 receptors on the detrusor, relaxing the bladder so it holds more urine.', 'Antimuscarinics also treat urge incontinence but can worsen confusion in older people.', 'So a β3 agonist is preferred in patients with cognitive impairment.']],
  ['NP-102', 'ASSOCIATION', 'Obstruction & urinary tract', 'Years of BPH with overflow leakage — what do the kidneys show?', 'Parenchymal pressure atrophy', ['Glomerular sclerosis', 'Hyperplastic arteriolar change', 'Ischemic tubular necrosis'], ['Long-standing bladder outlet obstruction pushes pressure back up the ureters into the kidneys.', 'The pelvis and calyces dilate, and the surrounding kidney tissue is compressed and thins (pressure atrophy).', 'Relieving the obstruction early can preserve kidney function.']],
  ['NP-103', 'MECHANISM', 'Water & sodium balance', 'Hypovolemic shock from a GI bleed — which kidney change happens?', 'Increased urea reabsorption', ['Decreased sodium reabsorption', 'Decreased urine osmolality', 'Increased renal blood flow'], ['Hypovolemia triggers ADH release, which inserts urea transporters in the inner medullary collecting duct.', 'Urea reabsorption builds the medullary gradient so the kidney can concentrate urine and save water.', 'This also raises BUN more than creatinine, which is why the BUN:Cr ratio exceeds 20 in prerenal states.']],
  ['NP-104', 'MECHANISM', 'Kidney stones', 'A ureteric stone obstructs the left kidney — what rises in that kidney?', 'Tubular hydrostatic pressure', ['Glomerular filtration', 'Glomerular capillary pressure', 'Bowman space oncotic pressure'], ['Urine cannot drain past the stone, so it backs up and pressure in the tubules and Bowman space rises.', 'Higher Bowman space pressure opposes filtration, so GFR in that kidney falls.', 'Most stones lodge at the narrow points: the ureteropelvic junction, the pelvic brim and the vesicoureteric junction.']],
  ['NP-105', 'ASSOCIATION', 'Renal physiology', 'GFR 0.1 L/min and renal plasma flow 0.5 L/min — filtration fraction', '0.2', ['0.1', '0.4', '0.5'], ['Filtration fraction is GFR divided by renal plasma flow, not renal blood flow.', 'Here 0.1 ÷ 0.5 = 0.2, which is the normal value of about 20%.', 'Autoregulation keeps renal flow and GFR steady across a wide range of blood pressures.']],
  ['NP-106', 'ASSOCIATION', 'Obstruction & urinary tract', 'Multiple sclerosis with urgency and incontinence — urodynamic finding', 'Bladder hypertonia', ['Large residual volume', 'Delayed bladder emptying', 'Elevated urethral pressure'], ['A spinal cord lesion above the sacral segments removes the brain\'s control over bladder reflexes.', 'The detrusor becomes spastic and contracts at small volumes, causing urgency and leakage.', 'Lower motor neuron lesions (sacral cord, cauda equina) instead cause a floppy bladder with retention.']],
  ['NP-107', 'MECHANISM', 'Obstruction & urinary tract', 'Frequent urination and leakage after an MS flare — explanation', 'Uninhibited bladder contraction', ['Detrusor muscle weakness', 'Pelvic laxity', 'Cystitis'], ['Multiple sclerosis disrupts the descending pathways that normally keep the detrusor quiet.', 'The bladder contracts before it is full, giving urgency, frequency and urge incontinence.', 'Antimuscarinic drugs or a β3 agonist calm the overactive detrusor.']],
  ['NP-108', 'MECHANISM', 'Pharmacology', 'Ramipril treatment: renin, angiotensin I, angiotensin II, aldosterone, bradykinin', 'Up, up, down, down, up', ['Up, up, up, down, up', 'Up, up, down, down, down', 'Down, down, down, down, same'], ['ACE inhibitors stop angiotensin I being converted to angiotensin II, so angiotensin II and aldosterone fall.', 'Less angiotensin II removes negative feedback, so renin and angiotensin I rise.', 'ACE also breaks down bradykinin, so bradykinin rises, causing cough and angioedema.']],
  ['NP-109', 'ASSOCIATION', 'Kidney stones', 'People with idiopathic calcium oxalate stones vs healthy controls — urine difference', 'Lower urinary citrate', ['Higher dietary calcium', 'Higher fluid intake', 'Lower dietary oxalate'], ['Citrate binds calcium in the urine, so less calcium is free to combine with oxalate.', 'Low urinary citrate is a common, treatable risk factor for calcium stones.', 'Potassium citrate corrects it; low dietary calcium actually increases oxalate absorption and stone risk.']],
  ['NP-110', 'ASSOCIATION', 'Glomerular disease', 'Poststreptococcal glomerulonephritis — feature that predicts a poor long-term outcome', 'Adult onset', ['Low C3 level', 'Gross hematuria', 'High antistreptolysin titer'], ['Over 95% of children recover completely from poststreptococcal glomerulonephritis.', 'Adults recover less often, and some progress to rapidly progressive glomerulonephritis or chronic kidney disease.', 'Low C3 is expected and returns to normal within about 8 weeks.']],
  ['NP-111', 'SIDE_EFFECT', 'Pharmacology', 'Leg cramps and weakness after starting chlorthalidone — cause', 'Hypokalemia', ['Hyponatremia', 'Hypocalcemia', 'Hypophosphatemia'], ['Thiazide diuretics deliver more sodium to the collecting duct, where it is swapped for potassium.', 'They also activate aldosterone through volume loss, adding to potassium loss.', 'Thiazides also cause low sodium, high calcium, high glucose and high uric acid.']],
  ['NP-112', 'ASSOCIATION', 'Renal physiology', 'Relationship between serum creatinine and GFR', 'Steep creatinine rise below GFR 60', ['Straight-line fall as GFR rises', 'Unchanged across all GFR', 'Flat until GFR 60, then falling'], ['Creatinine and GFR have an inverse, curved (hyperbolic) relationship.', 'Early loss of GFR barely changes creatinine, so a "normal" creatinine can hide significant kidney damage.', 'Once GFR falls below about 60 mL/min, small further losses cause large rises in creatinine.']],
  ['NP-113', 'ASSOCIATION', 'Renovascular disease', 'Atherosclerotic man with new severe hypertension from bilateral renal artery stenosis — renin, aldosterone, AT II, K⁺', 'High, high, high, low', ['High, high, high, high', 'Low, low, low, low', 'High, low, low, low'], ['Narrowed renal arteries make the kidneys sense low pressure, so they release renin.', 'Renin drives angiotensin II and aldosterone up, raising blood pressure.', 'Aldosterone makes the kidney waste potassium, so potassium is low.']],
  ['NP-114', 'MECHANISM', 'Renal physiology', 'Infused substance raises glomerular capillary pressure and net filtration pressure', 'Angiotensin II agonist', ['Alpha-adrenergic agonist', 'Prostaglandin inhibitor', 'Vasopressin-2 antagonist'], ['Angiotensin II constricts the efferent arteriole more than the afferent arteriole.', 'Blood backs up in the glomerulus, so capillary pressure and net filtration pressure rise.', 'Alpha-agonists and prostaglandin inhibitors constrict the afferent arteriole, which lowers glomerular pressure.']],
  ['NP-115', 'ASSOCIATION', 'Acute kidney injury', 'Military recruit with dark urine and muscle pain after training in heat — urine microscopy', 'Granular casts', ['Red blood cell casts', 'Dysmorphic red cells', 'Eosinophils'], ['Extreme exertion in the heat can break down muscle (rhabdomyolysis), releasing myoglobin.', 'Myoglobin injures the tubules, causing acute tubular necrosis.', 'Dead tubular cells form granular "muddy brown" casts in the urine.']],
  ['NP-116', 'ASSOCIATION', 'Renal tumors', 'Older man with painless visible hematuria who worked with rubber — likely finding', 'Bladder cancer', ['Prostate cancer', 'Staghorn calculus', 'Interstitial cystitis'], ['Painless visible blood in the urine in an older adult is bladder cancer until proved otherwise.', 'Aromatic amines in rubber, dye and leather work are occupational risks, along with smoking.', 'Most bladder cancers are urothelial carcinomas, diagnosed by cystoscopy.']],
  ['NP-117', 'ASSOCIATION', 'Kidney stones', 'First episode of renal colic — best advice to prevent another stone', 'Drink plenty of water daily', ['Follow a low-calcium diet', 'Follow a high-sodium diet', 'Complete an antibiotic course'], ['High fluid intake dilutes the urine and lowers the risk of every type of kidney stone.', 'The aim is to pass more than 2–2.5 litres of urine a day.', 'A low-calcium diet backfires, because more oxalate is absorbed from the gut.']],
  ['NP-118', 'MECHANISM', 'Acute kidney injury', 'Septic shock followed by acute kidney injury — underlying cause', 'Outer medullary ischemia', ['Glomerular inflammation', 'Neutrophilic tubulitis', 'Urinary tract obstruction'], ['Low blood pressure hits the outer medulla hardest, because it has little oxygen and works hard.', 'The straight proximal tubule and thick ascending limb there die, causing ischemic acute tubular necrosis.', 'Dead cells slough into the tubules and form muddy brown casts.']],
  ['NP-119', 'ASSOCIATION', 'Acute kidney injury', 'Which condition causes kidney pathology most like ischemic acute tubular necrosis?', 'Severe rhabdomyolysis', ['Diabetes mellitus', 'Minimal change disease', 'Systemic amyloidosis'], ['Rhabdomyolysis also causes acute tubular necrosis, but through toxic myoglobin rather than poor blood flow.', 'Both lead to dead tubular cells, casts and a sudden fall in GFR.', 'Aminoglycosides, contrast and cisplatin are other causes of toxic acute tubular necrosis.']],
  ['NP-120', 'BUZZWORD', 'Glomerular disease', 'Boy with facial puffiness and dark urine after a skin infection — what glows on immunofluorescence?', 'C3', ['C1q', 'IgE', 'Fibrin'], ['Poststreptococcal glomerulonephritis shows a granular, lumpy pattern of IgG, IgM and C3.', 'Complement is consumed by the immune complexes, so serum C3 is low.', 'Linear staining would instead suggest anti-GBM disease.']],
  ['NP-121', 'ASSOCIATION', 'Acute kidney injury', 'Severe dehydration on a thiazide — renal plasma flow, GFR and filtration fraction', 'Very low, low, increased', ['Very low, increased, reduced', 'Very low, low, reduced', 'Increased, increased, reduced'], ['In hypovolemia, angiotensin II constricts the efferent arteriole to keep glomerular pressure up.', 'Renal plasma flow falls sharply, but GFR is partly protected, so it falls less.', 'Because GFR falls less than plasma flow, the filtration fraction rises.']],
  ['NP-122', 'ASSOCIATION', 'Obstruction & urinary tract', 'Healthy 5-year-old who has never been dry at night — cause', 'Brain maturational delay', ['Bladder flaccidity', 'Osmotic diuresis', 'Posterior urethral valves'], ['Primary nocturnal enuresis means bedwetting after age 5 in a child who has never had a long dry spell.', 'It usually reflects slower maturation of bladder control and arousal, and often runs in families.', 'Most children outgrow it; bedwetting alarms and desmopressin help.']],
  ['NP-123', 'ASSOCIATION', 'Renal tumors', 'Older smoker with intermittent painless hematuria — major risk factor', 'Tobacco smoking', ['Testosterone therapy', 'Alcohol use', 'Travel history'], ['Smoking is the most important risk factor for urothelial carcinoma of the bladder.', 'Carcinogens from smoke are concentrated in urine, where they bathe the bladder lining.', 'Other risks include aromatic amines, cyclophosphamide and Schistosoma haematobium (squamous cell).']],
  ['NP-124', 'ASSOCIATION', 'Obstruction & urinary tract', 'Acute urinary retention from benign prostatic hyperplasia — increased risk of', 'Urinary tract infection', ['Bladder transitional cell carcinoma', 'Glomerulonephritis', 'Prostatic adenocarcinoma'], ['Incomplete emptying leaves residual urine in the bladder, where bacteria can multiply.', 'BPH is also linked to bladder stones, hydronephrosis and kidney damage.', 'BPH is not a precursor of prostate cancer.']],
  ['NP-125', 'ASSOCIATION', 'Renal tumors', 'Smoker with painless hematuria, weight loss, high calcium and a kidney mass', 'Renal cell carcinoma', ['Bladder cancer', 'Pheochromocytoma', 'Ureterolithiasis'], ['The classic triad of renal cell carcinoma is hematuria, flank pain and a flank mass, though few patients have all three.', 'It can secrete PTHrP, causing hypercalcemia, as well as erythropoietin and renin.', 'Smoking and obesity are the main risk factors.']],
  ['NP-126', 'ASSOCIATION', 'Obstruction & urinary tract', 'Blunt trauma with suprapubic pain, hematuria and free fluid in the peritoneum', 'Bladder dome rupture', ['Bladder neck rupture', 'Renal laceration', 'Anterior urethral transection'], ['The bladder dome is its weakest part and is the only part covered by peritoneum.', 'A blow to a full bladder ruptures the dome, spilling urine into the peritoneal cavity.', 'Intraperitoneal rupture needs surgical repair; extraperitoneal rupture with pelvic fracture can often be managed with a catheter.']],
  ['NP-127', 'ASSOCIATION', 'Chronic kidney disease', 'Polycystic kidney disease with CKD and bone pain — phosphate, PTH, calcitriol', 'High, high, low', ['Low, high, high', 'High, low, high', 'Low, high, low'], ['Failing kidneys cannot excrete phosphate or make calcitriol.', 'Both changes lower calcium, which drives PTH up (secondary hyperparathyroidism).', 'High PTH over years causes bone pain and renal osteodystrophy.']],
  ['NP-128', 'MECHANISM', 'Glomerular disease', 'Man with dark urine, joint pain and leg purpura who injects drugs — mechanism of kidney injury', 'Immune complexes from exogenous antigens', ['Immune complexes from endogenous antigens', 'Antibodies to glomerular antigens', 'Neutrophil-activating antibodies'], ['Hepatitis C, often from injecting drugs, can cause cryoglobulinemic vasculitis.', 'Antibodies against viral (exogenous) antigens form immune complexes that circulate and deposit in the kidney.', 'The usual kidney lesion is membranoproliferative glomerulonephritis, with low complement.']],
  ['NP-129', 'MECHANISM', 'Pharmacology', 'Heart failure patient started on spironolactone — what decreases?', 'Collecting duct H⁺ secretion', ['Proximal tubule H⁺ generation', 'Na⁺/K⁺/2Cl⁻ cotransport', 'Collecting duct urea reabsorption'], ['Spironolactone blocks the aldosterone receptor in the collecting duct.', 'Aldosterone normally drives sodium reabsorption and potassium and hydrogen ion secretion.', 'Blocking it can therefore cause hyperkalemia and a mild metabolic acidosis.']],
  ['NP-130', 'ASSOCIATION', 'Acid–base', 'Overdose of unknown pills with tinnitus — acid–base picture', 'Metabolic acidosis, respiratory alkalosis', ['Metabolic acidosis, respiratory acidosis', 'Metabolic alkalosis, respiratory acidosis', 'Metabolic and respiratory alkalosis'], ['Salicylates stimulate the breathing centre directly, causing an early respiratory alkalosis.', 'They also uncouple oxidative phosphorylation, so lactic and keto acids build up: an anion gap acidosis.', 'Treatment includes sodium bicarbonate to alkalinise the urine and hemodialysis if severe.']],
  ['NP-131', 'BUZZWORD', 'Glomerular disease', 'Hepatitis B with nephrotic syndrome; hypercellular glomeruli, split basement membranes', 'Membranoproliferative glomerulonephritis', ['Membranous nephropathy', 'Focal segmental glomerulosclerosis', 'Amyloidosis'], ['Membranoproliferative GN shows extra cells and a "tram-track" doubling of the basement membrane.', 'Subendothelial immune complexes are typical, with low complement.', 'Hepatitis B and C are common causes; hepatitis B is also linked to membranous nephropathy.']],
  ['NP-132', 'ASSOCIATION', 'Renovascular disease', 'Systemic sclerosis with sudden severe hypertension and kidney failure — injured structure', 'Small renal vessels', ['Renal glomeruli', 'Renal interstitium', 'Renal tubules'], ['Scleroderma renal crisis thickens the walls of small renal arteries, giving an "onion-skin" look.', 'Narrowed vessels cut renal blood flow, which drives renin and severe hypertension.', 'ACE inhibitors are the treatment and are life-saving.']],
  ['NP-133', 'BUZZWORD', 'Renal tumors', 'Back pain, anemia, kidney failure and a wide gamma gap; waxy casts block the tubules', 'Multiple myeloma', ['Lead nephropathy', 'Papillary necrosis', 'Ischemic tubular necrosis'], ['Myeloma plasma cells make excess light chains, which are filtered and form casts that block the tubules.', 'Myeloma kidney also comes from high calcium and AL amyloidosis.', 'A urine dipstick misses light chains, so urine protein electrophoresis is needed.']],
  ['NP-134', 'ASSOCIATION', 'Calcium & phosphate', 'Smoker with lethargy, polyuria and high calcium — which hormone is raised?', 'PTH-related protein', ['Parathyroid hormone', '1,25-dihydroxyvitamin D', 'ACTH'], ['Squamous cell lung cancer can secrete PTHrP, which acts like PTH on bone and kidney.', 'This causes humoral hypercalcemia of malignancy, with low PTH due to feedback.', 'High calcium causes nephrogenic diabetes insipidus, so patients pass large volumes of urine.']],
  ['NP-135', 'ASSOCIATION', 'Pharmacology', 'Idiopathic intracranial hypertension started on acetazolamide — PaCO₂, calcium, urine K⁺, urine pH', 'Down, down, up, up', ['Down, same, down, up', 'Up, down, up, down', 'Up, up, up, down'], ['Acetazolamide blocks bicarbonate reabsorption in the proximal tubule, causing a metabolic acidosis.', 'Bicarbonate in the urine makes it alkaline and carries potassium with it, while breathing increases to lower PaCO₂.', 'The acidosis increases calcium loss in the urine, which lowers serum calcium and raises the risk of calcium phosphate stones.']],
  ['NP-136', 'ASSOCIATION', 'Pharmacology', 'Acute angle-closure glaucoma treated with a drug that alkalinises the urine — where does it act?', 'Proximal convoluted tubule', ['Thick ascending limb', 'Distal convoluted tubule', 'Collecting duct'], ['Acetazolamide inhibits carbonic anhydrase, which the proximal tubule needs to reclaim bicarbonate.', 'Bicarbonate is lost in the urine, so the urine becomes alkaline.', 'In the eye it reduces aqueous humour production, which lowers pressure in glaucoma.']],
  ['NP-137', 'MECHANISM', 'Pharmacology', 'How does patiromer lower potassium in CKD?', 'Swaps calcium for potassium in the gut', ['Blocks aldosterone in the tubules', 'Stabilises cell membranes', 'Activates the Na⁺/K⁺ pump in muscle'], ['Patiromer is a non-absorbed polymer that releases calcium and binds potassium in the colon.', 'The bound potassium is passed in the stool, lowering total body potassium.', 'It works slowly, so it is for chronic hyperkalemia, letting patients stay on ACE inhibitors.']],
  ['NP-138', 'ASSOCIATION', 'Diabetic & hypertensive kidney', 'Screening test for early diabetic nephropathy', 'Urine albumin', ['Urine glucose', 'Urine ketones', 'Red blood cell casts'], ['The earliest sign of diabetic kidney damage is a small amount of albumin in the urine.', 'It is measured as the urine albumin-to-creatinine ratio, which a standard dipstick misses.', 'Screening starts 5 years after diagnosis in type 1 diabetes and at diagnosis in type 2.']],
  ['NP-139', 'ASSOCIATION', 'Renovascular disease', 'Atherosclerotic man with postprandial abdominal pain; one small kidney and one large', 'Renal artery stenosis', ['Fanconi syndrome', 'Myeloma kidney', 'Amyloidosis'], ['Atherosclerosis can narrow the renal artery, shrinking the kidney it supplies.', 'Pain after eating suggests the same disease is narrowing the mesenteric arteries (intestinal angina).', 'Renal artery stenosis causes hypertension through excess renin from the under-perfused kidney.']],
  ['NP-140', 'MECHANISM', 'Glomerular disease', 'Child with nephrotic syndrome — why is there protein in the urine?', 'Increased filtering of blood proteins', ['Poor tubular protein reabsorption', 'Overproduction of small proteins', 'Breakdown of skeletal muscle'], ['In minimal change disease the podocytes lose their negative charge and their foot processes flatten.', 'The filter then lets albumin through, causing selective proteinuria.', 'Steroids usually restore the filter within weeks.']],
  ['NP-141', 'ASSOCIATION', 'Congenital & developmental', 'Fetal ultrasound shows a horseshoe kidney — best counselling', 'Usually silent, but more urinary infections', ['Causes poor lung growth at birth', 'Often progresses to kidney failure', 'Raises lifelong aneurysm risk'], ['Most people with a horseshoe kidney have no symptoms throughout life.', 'Poor drainage raises the risk of infections, stones and hydronephrosis.', 'There is a slightly higher risk of Wilms tumour and an association with Turner syndrome.']],
  ['NP-142', 'ASSOCIATION', 'Acute kidney injury', 'Oliguria with muddy brown casts the day after cardiac bypass surgery', 'Tubule death from poor blood flow', ['Drug damage to the tubules', 'Glomerular inflammation', 'Crystals blocking the tubules'], ['Low blood flow during major surgery can kill tubular cells, causing ischemic acute tubular necrosis.', 'Muddy brown granular casts are the hallmark, with a urine sodium above 40 and FENa above 2%.', 'Tubular cells regenerate, so most patients recover over 1–3 weeks.']],
  ['NP-143', 'MECHANISM', 'Pharmacology', 'Beta blocker for hypertension: renin, AT I, AT II, aldosterone, bradykinin', 'Low, low, low, low, unchanged', ['High, low, low, low, unchanged', 'High, high, low, low, low', 'High, high, high, low, unchanged'], ['Juxtaglomerular cells release renin when β1 receptors are stimulated.', 'Beta blockers reduce renin, so angiotensin I, angiotensin II and aldosterone all fall.', 'Bradykinin is untouched, unlike with ACE inhibitors.']],
  ['NP-144', 'ASSOCIATION', 'Obstruction & urinary tract', 'Older man with hesitancy, weak stream, nocturia and painless hematuria — source of blood', 'Fragile new prostate vessels', ['Bladder cancer', 'Glomerular inflammation', 'Acquired bleeding disorder'], ['Benign prostatic hyperplasia grows new, fragile blood vessels that can bleed into the urine.', 'BPH arises in the transition zone, which is why it compresses the urethra early.', 'Painless hematuria still needs imaging and cystoscopy to rule out cancer.']],

  // ── NP-145 … NP-190 ──────────────────────────────────────────────────────
  ['NP-145', 'ASSOCIATION', 'Calcium & phosphate', 'Elderly woman with back pain, anemia and high calcium from myeloma — PTH, urine Ca, calcitriol, PTHrP', 'Low, high, low, normal', ['Low, high, normal, high', 'High, high, high, normal', 'Low, low, normal, normal'], ['Myeloma raises calcium by activating osteoclasts directly, not through PTH or PTHrP.', 'High calcium suppresses PTH, and low PTH means less calcitriol is made.', 'The extra calcium filtered by the kidneys spills into the urine.']],
  ['NP-146', 'ASSOCIATION', 'Acid–base', 'Four-week-old with projectile non-bilious vomiting — blood gas', 'pH 7.49, PaCO₂ 46, HCO₃⁻ 34', ['pH 7.29, PaCO₂ 30, HCO₃⁻ 14', 'pH 7.30, PaCO₂ 55, HCO₃⁻ 26', 'pH 7.41, PaCO₂ 39, HCO₃⁻ 24'], ['Projectile non-bilious vomiting at 3–6 weeks is pyloric stenosis.', 'Losing stomach acid causes a hypochloremic, hypokalemic metabolic alkalosis.', 'The lungs compensate by slowing breathing, so PaCO₂ rises slightly.']],
  ['NP-147', 'ASSOCIATION', 'Congenital & developmental', 'Boy with recurrent UTIs and a pouch running from the bladder toward the umbilicus', 'Urachus', ['Ureter', 'Omphalomesenteric duct', 'Umbilical artery'], ['The urachus links the fetal bladder to the umbilicus and normally closes into the median umbilical ligament.', 'If the bladder end stays open, it forms a urachal diverticulum where urine pools and infections recur.', 'If the whole tract stays open, urine leaks from the umbilicus (patent urachus).']],
  ['NP-148', 'ASSOCIATION', 'Chronic kidney disease', 'Advanced CKD from untreated hypertension — expected blood gas', 'pH 7.25, HCO₃⁻ 12, PaCO₂ 28, gap 20', ['pH 7.31, HCO₃⁻ 18, PaCO₂ 37, gap 12', 'pH 7.15, HCO₃⁻ 16, PaCO₂ 48, gap 18', 'pH 7.32, HCO₃⁻ 25, PaCO₂ 50, gap 10'], ['Failing kidneys cannot excrete acids such as sulfate and phosphate, so an anion gap acidosis develops.', 'The lungs compensate by breathing harder and lowering PaCO₂.', 'Earlier CKD often causes a non-anion gap acidosis, before the anions accumulate.']],
  ['NP-149', 'ASSOCIATION', 'Pharmacology', 'Diuretic overdose: low sodium, high calcium, low potassium and alkalosis', 'Hydrochlorothiazide', ['Torsemide', 'Spironolactone', 'Acetazolamide'], ['Thiazides are the diuretics that raise serum calcium, by increasing calcium reabsorption in the distal tubule.', 'They also commonly cause hyponatremia, because they impair the kidney\'s ability to dilute urine.', 'Loop diuretics instead lower calcium, and spironolactone raises potassium.']],
  ['NP-150', 'ASSOCIATION', 'Obstruction & urinary tract', 'Catheter-associated UTI after hip surgery — most effective prevention', 'Remove the catheter when not needed', ['Use antibiotic-coated catheters', 'Replace catheters on a schedule', 'Give preventive antibiotics'], ['The risk of catheter-associated infection rises every day the catheter stays in.', 'Removing it as soon as it is no longer needed is the most effective prevention.', 'Routine catheter changes, bladder irrigation and preventive antibiotics do not help and promote resistance.']],
  ['NP-151', 'ASSOCIATION', 'Acid–base', 'Metabolic alkalosis of unclear cause — most useful test', 'Urine chloride', ['Serum osmolality', 'Serum ketones', 'Urine glucose'], ['A low urine chloride (below 20) means the body is chloride- and volume-depleted, as with vomiting or past diuretic use.', 'A high urine chloride points to ongoing diuretic use or mineralocorticoid excess.', 'Urine chloride is more reliable than urine sodium when bicarbonate is spilling into the urine.']],
  ['NP-152', 'MECHANISM', 'Acute kidney injury', 'Cirrhosis on furosemide with worsening ascites after ibuprofen — prostaglandins, GFR, urine sodium', 'Low, low, low', ['Low, unchanged, low', 'High, high, high', 'Unchanged, low, high'], ['In cirrhosis, kidney blood flow depends on prostaglandins to keep the afferent arteriole open.', 'NSAIDs block prostaglandins, so GFR falls and the kidneys hold on to more sodium.', 'Less sodium excreted means more fluid retained and worse ascites; NSAIDs should be avoided in cirrhosis.']],
  ['NP-153', 'MECHANISM', 'Electrolytes', 'Low potassium during a cocaine-induced heart attack — cause', 'Potassium shifting into cells', ['Potassium lost in the urine', 'Too little dietary potassium', 'Potassium lost in the gut'], ['Stress and cocaine release catecholamines, which stimulate β2 receptors.', 'β2 stimulation activates the Na⁺/K⁺-ATPase, pulling potassium into cells.', 'Insulin and alkalosis shift potassium into cells in the same way.']],
  ['NP-154', 'ASSOCIATION', 'Acute kidney injury', 'Oliguria after hemorrhage that recovers with fluids — result showing kidney compensation', 'Urine sodium below 20 mEq/L', ['Urine osmolality below 350', 'Muddy brown casts', 'FENa above 2%'], ['In prerenal injury the tubules are healthy, so they hold on to sodium to restore volume.', 'That gives a low urine sodium, a FENa below 1% and concentrated urine.', 'Muddy brown casts and a FENa above 2% mean tubular damage (acute tubular necrosis) instead.']],
  ['NP-155', 'ASSOCIATION', 'Renal physiology', 'Even in severe dehydration, where is most filtered water reabsorbed?', 'Proximal tubule', ['Medullary collecting duct', 'Loop of Henle', 'Cortical collecting duct'], ['The proximal tubule reabsorbs about two-thirds of filtered water no matter what the ADH level is.', 'ADH only fine-tunes the last few percent in the collecting duct.', 'That small fine-tuning still makes the difference between dilute and very concentrated urine.']],
  ['NP-156', 'ASSOCIATION', 'Obstruction & urinary tract', 'Pelvic surgery: the ureter lies directly in front of which artery in the true pelvis?', 'Internal iliac artery', ['Uterine artery', 'Gonadal vein', 'Inferior vena cava'], ['The ureter crosses the pelvic brim at the iliac bifurcation and runs down in front of the internal iliac artery.', 'Lower down it passes under the uterine artery, where it is at risk during hysterectomy.', 'Remember "water under the bridge": the ureter (water) runs under the uterine artery (bridge).']],
  ['NP-157', 'MECHANISM', 'Pharmacology', 'Drug that lowers the maximum rate of renal glucose reabsorption', 'Canagliflozin', ['Metformin', 'Liraglutide', 'Sitagliptin'], ['Canagliflozin blocks SGLT2 in the proximal tubule, which normally reclaims most filtered glucose.', 'Lowering the transport maximum makes glucose spill into the urine at lower blood levels.', 'Side effects include genital fungal infections, UTIs, volume loss and euglycemic ketoacidosis.']],
  ['NP-158', 'ASSOCIATION', 'Chronic kidney disease', 'Long-term hemodialysis patient with carpal tunnel and painful shoulders — explanation', 'β2-microglobulin deposition', ['Mutated transthyretin deposition', 'Light chains from clonal cells', 'Overproduced amyloid A'], ['β2-microglobulin is normally cleared by the kidneys, but dialysis removes it poorly.', 'It builds up and forms amyloid in joints and tendons, causing carpal tunnel and shoulder pain.', 'This is dialysis-related amyloidosis; a kidney transplant stops its progression.']],
  ['NP-159', 'ASSOCIATION', 'Electrolytes', 'Teenager secretly misusing laxatives — potassium, bicarbonate, aldosterone', 'Low, high, high', ['Low, low, low', 'High, low, normal', 'High, high, high'], ['Chronic diarrhoea loses potassium and fluid, and the volume loss raises aldosterone.', 'Aldosterone drives more potassium and hydrogen ion loss in the urine.', 'The net effect is often a metabolic alkalosis, unlike the acidosis of acute diarrhoea.']],
  ['NP-160', 'ASSOCIATION', 'Obstruction & urinary tract', 'Girl with hypertension and a history of repeated kidney infections — cause', 'Reflux nephropathy', ['Posterior urethral valves', 'Polycystic kidney disease', 'Malignant hypertension'], ['Vesicoureteral reflux carries infected urine up to the kidneys, causing repeated pyelonephritis.', 'Each infection scars the kidney, especially at the poles, a pattern called reflux nephropathy.', 'Scarred kidneys release renin and can cause hypertension and chronic kidney disease.']],
  ['NP-161', 'BUZZWORD', 'Glomerular disease', 'Adult nephrotic syndrome; EM shows irregular dense deposits on the basement membrane', 'Membranous nephropathy', ['Minimal change disease', 'Crescentic glomerulonephritis', 'Focal segmental glomerulosclerosis'], ['Subepithelial immune deposits on the basement membrane define membranous nephropathy.', 'The basement membrane grows "spikes" around the deposits, seen on silver stain.', 'Secondary causes include lupus, hepatitis B, solid tumours and drugs.']],
  ['NP-162', 'ASSOCIATION', 'Acid–base', 'Blood gas moves from baseline to lower pH, lower bicarbonate and lower PaCO₂', 'Metabolic acidosis', ['Respiratory acidosis', 'Metabolic alkalosis', 'Respiratory alkalosis'], ['A low pH with a low bicarbonate is a primary metabolic acidosis.', 'The fall in PaCO₂ is the lungs compensating, not the cause.', 'Winter\'s formula predicts the expected PaCO₂: 1.5 × bicarbonate + 8 (± 2).']],
  ['NP-163', 'ASSOCIATION', 'Acid–base', 'High anion gap acidosis that resolves within hours of treatment — what was given?', 'Insulin and normal saline', ['A mineralocorticoid', 'An IV loop diuretic', 'An opioid antagonist'], ['Diabetic ketoacidosis resolves quickly once insulin stops ketone production and fluids restore volume.', 'Potassium must be watched and replaced, because insulin drives it into cells.', 'The anion gap closing is the sign that ketoacidosis has resolved.']],
  ['NP-164', 'BUZZWORD', 'Glomerular disease', 'Young man with hemoptysis and rapidly progressive kidney failure — antibody target', 'Type IV collagen α3 chain', ['Double-stranded DNA', 'Streptococcal surface antigens', 'Topoisomerase I'], ['Goodpasture syndrome is caused by antibodies to the α3 chain of type IV collagen.', 'That collagen is in both the glomerular and alveolar basement membranes, so kidneys and lungs are hit together.', 'Treatment is plasmapheresis to remove the antibodies, plus steroids and cyclophosphamide.']],
  ['NP-165', 'MECHANISM', 'Renal physiology', 'Mild selective efferent arteriole constriction — GFR and filtration fraction', 'GFR rises, FF rises', ['GFR falls, FF rises', 'GFR falls, FF unchanged', 'GFR rises, FF falls'], ['Narrowing the outflow raises pressure inside the glomerular capillaries, so GFR goes up.', 'Plasma flow falls slightly, so the filtration fraction rises.', 'Severe efferent constriction eventually lowers GFR, because flow drops too much.']],
  ['NP-166', 'ASSOCIATION', 'Chronic kidney disease', 'Which kidney cells make erythropoietin?', 'Peritubular interstitial cells', ['Juxtaglomerular cells', 'Glomerular podocytes', 'Proximal tubule epithelium'], ['Erythropoietin is made by fibroblast-like interstitial cells around the tubules of the renal cortex.', 'They sense low oxygen through HIF and increase erythropoietin when oxygen falls.', 'In CKD these cells are lost, causing a normocytic anemia.']],
  ['NP-167', 'ASSOCIATION', 'Acute kidney injury', 'Oliguria after cardiac arrest — which structures show ischemic injury?', 'Proximal tubules', ['Glomeruli', 'Renal papillae', 'Collecting ducts'], ['The straight part of the proximal tubule and the thick ascending limb are the most vulnerable to low blood flow.', 'They work hard and sit in the oxygen-poor outer medulla.', 'Their injury causes ischemic acute tubular necrosis with muddy brown casts.']],
  ['NP-168', 'ASSOCIATION', 'Glomerular disease', 'Boy with periorbital edema and red cell casts — additional finding', 'Low serum C3 level', ['Low serum C4 level', 'Anti-GBM antibodies', 'Raised eosinophil count'], ['Poststreptococcal glomerulonephritis activates complement through the alternative pathway.', 'So C3 is low while C4 is usually normal.', 'C3 returns to normal within about 8 weeks; if it stays low, consider membranoproliferative GN.']],
  ['NP-169', 'TRIAD', 'Renovascular disease', 'Fever, confusion, low platelets, hemolysis and acute kidney injury — kidney biopsy', 'Platelet-rich thrombi in small vessels', ['Glomerular crescents', 'Mesangial IgA deposits', 'Collapsed, scarred tufts'], ['This is thrombotic thrombocytopenic purpura, caused by low ADAMTS13 activity.', 'Huge von Willebrand multimers build up and trigger platelet clots in small vessels, shearing red cells (schistocytes).', 'Treatment is urgent plasma exchange.']],
  ['NP-170', 'ASSOCIATION', 'Glomerular disease', 'Boy with colicky abdominal pain, bloody stool and red urine — additional finding', 'Joint pain', ['Painful mouth ulcers', 'Honey-crusted rash', 'Generalised lymphadenopathy'], ['Abdominal pain, GI bleeding and kidney involvement in a child suggest IgA vasculitis (Henoch–Schönlein purpura).', 'The classic tetrad is palpable purpura, joint pain, abdominal pain and kidney disease.', 'Intussusception is an important complication.']],
  ['NP-171', 'BUZZWORD', 'Tubulointerstitial disease', 'Rash, fever and kidney injury after starting indomethacin for gout', 'Interstitial nephritis', ['Uric acid nephropathy', 'Renal tubular necrosis', 'Pyelonephritis'], ['Acute interstitial nephritis is an allergic reaction in the kidney to a drug.', 'Common triggers are NSAIDs, penicillins, cephalosporins, PPIs, diuretics and rifampin.', 'Urine shows white cells and white cell casts, sometimes eosinophils; stop the drug.']],
  ['NP-172', 'ASSOCIATION', 'Acute kidney injury', 'Gastroenteritis with orthostatic hypotension — ADH, norepinephrine, angiotensin II, endothelin', 'All four raised', ['All four lowered', 'ADH up, others down', 'All raised except endothelin'], ['Low blood volume triggers every vasoconstrictor system at once to support blood pressure.', 'ADH and angiotensin II also make the kidney hold on to water and salt.', 'Endothelin constricts renal vessels, which can tip prerenal injury into tubular damage.']],
  ['NP-173', 'ASSOCIATION', 'Kidney stones', 'Recurrent calcium kidney stones — drug to prevent more', 'Hydrochlorothiazide', ['Furosemide', 'Acetazolamide', 'Mannitol'], ['Thiazides increase calcium reabsorption in the distal tubule, so less calcium reaches the urine.', 'Less urinary calcium means fewer calcium stones.', 'Loop diuretics and acetazolamide do the opposite and can promote stones.']],
  ['NP-174', 'ASSOCIATION', 'Cystic kidney disease', 'Fetal ultrasound: both kidneys enlarged and full of tiny cysts — finding at birth', 'Pulmonary hypoplasia', ['Cerebral aneurysms', 'Intestinal atresia', 'Facial hemangiomas'], ['Large kidneys full of small cysts before birth suggest autosomal recessive polycystic kidney disease.', 'The kidneys make little urine, causing oligohydramnios and Potter sequence with underdeveloped lungs.', 'Survivors also develop congenital hepatic fibrosis and portal hypertension.']],
  ['NP-175', 'ASSOCIATION', 'Glomerular disease', 'Teen on daily ibuprofen with nephrotic syndrome and normal glomeruli on light microscopy', 'Minimal change disease', ['Membranous nephropathy', 'Acute interstitial nephritis', 'Focal segmental glomerulosclerosis'], ['Glomeruli that look normal on light microscopy despite heavy protein loss mean minimal change disease.', 'NSAIDs can trigger it, sometimes together with interstitial nephritis.', 'Stopping the drug and giving steroids usually brings remission.']],
  ['NP-176', 'ASSOCIATION', 'Water & sodium balance', 'Urine stays dilute during water deprivation, then concentrates after vasopressin', 'Central diabetes insipidus', ['Primary polydipsia', 'Nephrogenic diabetes insipidus', 'Post-obstructive polyuria'], ['In central diabetes insipidus the pituitary makes too little ADH, but the kidney responds normally to it.', 'So urine stays dilute when water is withheld but concentrates after desmopressin.', 'Causes include head injury, surgery, tumours and idiopathic disease; treat with desmopressin.']],
  ['NP-177', 'ASSOCIATION', 'Water & sodium balance', 'Infant with nephrogenic diabetes insipidus — treatment besides water', 'Hydrochlorothiazide', ['Desmopressin', 'Salt tablets', 'Hydrocortisone'], ['Thiazides cause mild volume depletion, so the proximal tubule reabsorbs more salt and water.', 'Less fluid reaches the collecting duct, which reduces urine output paradoxically.', 'Desmopressin does not help, because the kidney cannot respond to ADH.']],
  ['NP-178', 'MECHANISM', 'Acid–base', 'Hiker at 4,000 m for three days — pH, H⁺ secretion and bicarbonate reabsorption', 'pH up, H⁺ down, HCO₃⁻ down', ['pH down, H⁺ up, HCO₃⁻ down', 'pH up, H⁺ same, HCO₃⁻ down', 'pH up, H⁺ up, HCO₃⁻ same'], ['Low oxygen at altitude makes you breathe faster, blowing off CO₂ and causing respiratory alkalosis.', 'Over days, the kidneys compensate by secreting less acid and excreting more bicarbonate.', 'Acetazolamide speeds this adaptation and helps prevent altitude sickness.']],
  ['NP-179', 'TRIAD', 'Glomerular disease', 'Hematuria, nasal congestion and rapidly rising creatinine with few immune deposits', 'Antineutrophil cytoplasmic antibodies', ['Low serum C3 level', 'Anti-GBM antibodies', 'Antiphospholipid antibodies'], ['Kidney failure with upper airway disease and few immune deposits (pauci-immune) suggests ANCA vasculitis.', 'Granulomatosis with polyangiitis is usually PR3-ANCA (c-ANCA) positive.', 'It causes rapidly progressive glomerulonephritis and is treated with steroids and rituximab or cyclophosphamide.']],
  ['NP-180', 'ASSOCIATION', 'Congenital & developmental', 'Newborn boy with urosepsis, distended bladder and bilateral hydronephrosis — cause', 'Persistent urogenital membrane', ['Short intravesical ureters', 'Ureteropelvic junction narrowing', 'Fused metanephric blastemas'], ['Posterior urethral valves are folds of tissue left from the urogenital membrane in the posterior urethra.', 'They block urine outflow, so the bladder, both ureters and both kidneys dilate.', 'They are the most common cause of bladder outlet obstruction in newborn boys.']],
  ['NP-181', 'SIDE_EFFECT', 'Water & sodium balance', 'Woman on bipolar medication with polyuria and dilute urine despite fasting — impaired segment', 'Collecting duct', ['Thick ascending limb', 'Proximal convoluted tubule', 'Early distal tubule'], ['Lithium enters collecting duct cells through sodium channels and blocks the response to ADH.', 'This causes nephrogenic diabetes insipidus, with dilute urine that does not respond to desmopressin.', 'Amiloride blocks lithium entry into these cells and can help.']],
  ['NP-182', 'MECHANISM', 'Calcium & phosphate', 'Perioral tingling and cramps after thyroidectomy — what increased?', 'Urinary calcium excretion', ['Calcium release from bone', 'Calcium binding by albumin', 'Vitamin D hydroxylation'], ['Thyroid surgery can damage the parathyroids, causing a sudden drop in PTH.', 'Without PTH the distal tubule reabsorbs less calcium, so more is lost in the urine.', 'PTH loss also cuts bone release and calcitriol, so calcium falls and phosphate rises.']],
  ['NP-183', 'MECHANISM', 'Renal tumors', 'Renal tumour cells that look empty on biopsy — why?', 'Glycogen and lipid accumulation', ['Mitochondrial swelling', 'Fragmented nuclei', 'Membrane lipid peroxidation'], ['Clear cell renal cell carcinoma stores glycogen and lipid, which dissolve during processing.', 'That leaves cells that look empty or clear under the microscope.', 'It is the most common type of renal cell carcinoma and is linked to VHL loss.']],
  ['NP-184', 'ASSOCIATION', 'Acid–base', 'Diabetic nephropathy with type 4 RTA — serum sodium, urine potassium, urine ammonium', 'Normal, low, low', ['Low, high, unchanged', 'High, low, high', 'Low, unchanged, high'], ['Type 4 RTA is caused by low aldosterone or resistance to it, common in diabetic kidney disease.', 'Without aldosterone the collecting duct secretes less potassium, so potassium rises.', 'High potassium also suppresses ammonia production, so urine ammonium falls and acidosis develops.']],
  ['NP-185', 'ASSOCIATION', 'Renal physiology', 'GFR 100 mL/min and renal plasma flow 500 mL/min — filtration fraction', '20%', ['10%', '30%', '40%'], ['Filtration fraction equals GFR divided by renal plasma flow: 100 ÷ 500 = 20%.', 'GFR can be estimated from inulin or creatinine clearance, and plasma flow from PAH clearance.', 'Efferent constriction raises filtration fraction, and afferent constriction leaves it about the same.']],
  ['NP-186', 'MECHANISM', 'Electrolytes', 'Asthma attack treated with many albuterol nebulisers — why is potassium low?', 'Intracellular shift of potassium', ['Urinary potassium loss', 'Respiratory acidosis', 'Sweat potassium loss'], ['β2 agonists stimulate the Na⁺/K⁺-ATPase, moving potassium into cells.', 'Total body potassium is unchanged; it has just moved.', 'Nebulised albuterol is used for the same reason to treat hyperkalemia.']],
  ['NP-187', 'ASSOCIATION', 'Acid–base', 'Young man with fruity-smelling urine, polyuria and vomiting — acid–base values', 'pH low, PaCO₂ low, HCO₃⁻ low', ['pH low, PaCO₂ high, HCO₃⁻ high', 'pH high, PaCO₂ low, HCO₃⁻ low', 'pH normal, PaCO₂ normal, HCO₃⁻ normal'], ['Diabetic ketoacidosis causes an anion gap metabolic acidosis, so pH and bicarbonate are low.', 'The lungs compensate with deep, fast breathing (Kussmaul), lowering PaCO₂.', 'Treatment is fluids, insulin and potassium replacement.']],
  ['NP-188', 'ASSOCIATION', 'Pharmacology', 'Young man with severe hypertension, low potassium and suppressed renin — drug prescribed', 'Spironolactone', ['Captopril', 'Amlodipine', 'Hydrochlorothiazide'], ['High blood pressure with low potassium and low renin suggests primary hyperaldosteronism.', 'Spironolactone blocks the aldosterone receptor, correcting both blood pressure and potassium.', 'An adrenal adenoma (Conn syndrome) can be removed surgically.']],
  ['NP-189', 'ASSOCIATION', 'Renovascular disease', 'Months after clipping a renal artery — which cells multiply?', 'Afferent arteriole muscle cells', ['Proximal tubule epithelium', 'Mesangial cells', 'Efferent arteriole endothelium'], ['Juxtaglomerular cells are modified smooth muscle cells in the afferent arteriole wall that make renin.', 'Low perfusion stimulates them to make more renin and to multiply (hyperplasia).', 'This drives hypertension in renal artery stenosis.']],
  ['NP-190', 'MECHANISM', 'Water & sodium balance', 'After desmopressin, clearance of which substance falls the most?', 'Urea', ['Creatinine', 'Glucose', 'Para-aminohippuric acid'], ['Desmopressin inserts urea transporters in the inner medullary collecting duct.', 'More urea is reabsorbed, so its clearance falls.', 'Creatinine and PAH clearance depend on filtration and secretion, which ADH barely changes.']],

  // ── NP-191 … NP-236 ──────────────────────────────────────────────────────
  ['NP-191', 'ASSOCIATION', 'Acute kidney injury', 'Found unresponsive, high anion gap, envelope-shaped crystals in urine — cause of kidney injury', 'Tubular injury from a swallowed toxin', ['Filtered light chain injury', 'Glomerular microthrombi', 'Excess parathyroid hormone'], ['Ethylene glycol (antifreeze) is broken down to glycolic and oxalic acid, causing a high anion gap acidosis.', 'Oxalate binds calcium and forms envelope-shaped calcium oxalate crystals that injure the tubules.', 'Treatment is fomepizole to block alcohol dehydrogenase, and dialysis if severe.']],
  ['NP-192', 'ASSOCIATION', 'Obstruction & urinary tract', 'Transplanted kidney: which artery supplies the healthy upper part of the donor ureter?', 'Renal artery', ['Internal iliac artery', 'Superior vesical artery', 'Common iliac artery'], ['In the body, the ureter gets blood from several arteries along its length.', 'In a transplant only the donor renal artery is connected, so it alone feeds the transplanted ureter from above.', 'The far end of the donor ureter is therefore the most likely to become ischemic and leak or narrow.']],
  ['NP-193', 'ASSOCIATION', 'Obstruction & urinary tract', 'Older man with no urine for 24 hours, a full bladder and bilateral hydronephrosis — cause', 'Urethral compression', ['Interstitial nephritis', 'Ischemic tubular injury', 'Diabetic nephropathy'], ['Benign prostatic hyperplasia can squeeze the urethra shut, causing acute urinary retention.', 'Urine backs up into both kidneys, causing post-renal acute kidney injury.', 'A urinary catheter relieves it, often followed by a large diuresis.']],
  ['NP-194', 'ASSOCIATION', 'Renovascular disease', 'Blue painful toe and rising creatinine days after coronary angiography — kidney biopsy', 'Cholesterol clefts in arteries', ['Glomerular crescents', 'Proximal tubular necrosis', 'Urate crystals in tubules'], ['Catheters can scrape cholesterol from aortic plaques, which then lodge in small arteries downstream.', 'In the kidney this causes atheroembolic disease, seen as needle-shaped clefts where cholesterol was.', 'Other clues are livedo reticularis, blue toes and eosinophilia.']],
  ['NP-195', 'ASSOCIATION', 'Glomerular disease', 'Child with nephrotic syndrome — secondary change', 'Increased liver lipoprotein synthesis', ['Decreased liver albumin synthesis', 'Increased renal sodium wasting', 'Decreased plasma aldosterone'], ['Low oncotic pressure from albumin loss stimulates the liver to make more proteins, including lipoproteins.', 'Lipoprotein breakdown is also reduced, so cholesterol and triglycerides rise.', 'Fat may appear in the urine as fatty casts and oval fat bodies.']],
  ['NP-196', 'ASSOCIATION', 'Tubulointerstitial disease', 'Young man with sudden painless gross hematuria whose sister has sickle cell disease', 'Papillary necrosis', ['Acute pyelonephritis', 'Renal artery stenosis', 'Urate nephropathy'], ['The renal medulla has low oxygen and high osmolality, which makes red cells sickle even in sickle cell trait.', 'Sickled cells block the vessels to the papillae, which die and slough off.', 'This causes painless, sometimes heavy, blood in the urine.']],
  ['NP-197', 'ASSOCIATION', 'Electrolytes', 'Bulimic patient secretly taking furosemide — serum HCO₃⁻, serum Cl⁻, urine Na⁺, urine K⁺', 'High, low, high, high', ['Low, low, high, high', 'High, high, normal, high', 'Low, normal, normal, low'], ['Loop diuretics cause a hypokalemic, hypochloremic metabolic alkalosis.', 'Soon after a dose, the urine is full of sodium, chloride and potassium.', 'Vomiting gives the same blood picture but with low urine chloride.']],
  ['NP-198', 'MECHANISM', 'Glomerular disease', 'Child with massive proteinuria after a cold and normal creatinine — cause of the protein loss', 'Loss of basement membrane anions', ['Glomerular crescents', 'Basement membrane thinning', 'Nodular glomerular scarring'], ['The glomerular filter normally repels albumin because both carry a negative charge.', 'In minimal change disease that charge barrier is lost, so albumin passes through.', 'Podocyte foot processes flatten, seen only on electron microscopy.']],
  ['NP-199', 'ASSOCIATION', 'Kidney stones', 'Young man with a first calcium kidney stone — likely lab finding', 'Normal blood calcium, high urine calcium', ['High blood calcium, high urine calcium', 'Normal blood calcium, high urine oxalate', 'High blood uric acid, high urine uric acid'], ['Most calcium stones come from idiopathic hypercalciuria, with normal blood calcium.', 'The kidneys simply excrete more calcium than usual.', 'Thiazides, high fluid intake and a low-salt diet reduce urine calcium.']],
  ['NP-200', 'ASSOCIATION', 'Glomerular disease', 'Nephrotic syndrome; biopsy shows apple-green birefringence with Congo red — next test', 'Serum protein electrophoresis', ['24-hour urine copper', 'Serum total bilirubin', '24-hour urine uric acid'], ['Apple-green birefringence with Congo red means amyloid.', 'In an adult without chronic inflammation, AL amyloid from a plasma cell clone is the main concern.', 'Serum protein electrophoresis and free light chains look for the monoclonal protein.']],
  ['NP-201', 'ASSOCIATION', 'Kidney stones', 'Removed kidney filled with a branching staghorn stone after recurrent UTIs — further finding', 'Klebsiella infection', ['Escherichia coli infection', 'Persistently low urine pH', 'High urinary cystine'], ['Staghorn stones are usually struvite, made when urease-producing bacteria alkalinise the urine.', 'Urease producers include Proteus, Klebsiella and Staphylococcus saprophyticus.', 'E. coli does not make urease, so it does not form struvite stones.']],
  ['NP-202', 'ASSOCIATION', 'Pharmacology', 'Heart failure on high-dose furosemide; acetazolamide is added — why?', 'Metabolic alkalosis', ['Hypokalemia', 'Prerenal azotemia', 'Hyperuricemia'], ['Loop diuretics cause a contraction alkalosis by removing fluid and stimulating acid loss.', 'Acetazolamide makes the kidney excrete bicarbonate, correcting the alkalosis.', 'This matters in COPD, where alkalosis can suppress the drive to breathe.']],
  ['NP-203', 'MECHANISM', 'Glomerular disease', 'Young woman with arthritis, mouth ulcers, cytopenias and red cell casts — kidney mechanism', 'DNA–anti-DNA immune complexes', ['Light chain deposition', 'Antibodies to podocyte antigens', 'Bacterial antigen complexes'], ['Lupus nephritis is caused by immune complexes of DNA and anti-DNA antibodies lodging in the glomeruli.', 'Complement is consumed, so C3 and C4 are low.', 'Diffuse proliferative (class IV) nephritis is the most common and most serious form.']],
  ['NP-204', 'ASSOCIATION', 'Glomerular disease', 'Nephrotic syndrome after 25 years of uncontrolled rheumatoid arthritis — glomeruli', 'Deposition of amorphous material', ['Mesangial IgA deposition', 'Glomerular crescents', 'Normal light microscopy'], ['Long-standing inflammation keeps serum amyloid A high, which can deposit as AA amyloid.', 'In the glomeruli it appears as pale, shapeless (amorphous) material that stains with Congo red.', 'Other causes of AA amyloid include chronic infections and familial Mediterranean fever.']],
  ['NP-205', 'ASSOCIATION', 'Calcium & phosphate', 'Perioral tingling, cramps and a positive Chvostek sign — likely history', 'Recent thyroid surgery', ['Excessive vitamin D intake', 'New chlorthalidone prescription', 'Frequent antacid use'], ['Facial twitching on tapping (Chvostek sign), cramps and tingling are signs of low calcium.', 'The most common cause of sudden low calcium is parathyroid damage during thyroid surgery.', 'Vitamin D excess and thiazides raise calcium instead.']],
  ['NP-206', 'ASSOCIATION', 'Acid–base', 'Opioid overdose with slow, shallow breathing — acid–base pattern', 'Low pH, high CO₂, slightly high HCO₃⁻', ['Normal pH, high CO₂, high HCO₃⁻', 'Low pH, low CO₂, low HCO₃⁻', 'High pH, low CO₂, slightly low HCO₃⁻'], ['Opioids depress breathing, so CO₂ builds up and pH falls: acute respiratory acidosis.', 'In the first hours, bicarbonate rises only slightly from buffering.', 'Naloxone reverses the opioid and restores breathing.']],
  ['NP-207', 'ASSOCIATION', 'Chronic kidney disease', 'Advanced diabetic CKD — parathyroid hormone and free calcium', 'High PTH, low calcium', ['High PTH, high calcium', 'Low PTH, low calcium', 'Normal PTH, normal calcium'], ['Kidney failure causes phosphate retention and low calcitriol, both of which lower free calcium.', 'Low calcium drives the parathyroids to make more PTH: secondary hyperparathyroidism.', 'After years, the glands may act on their own and raise calcium (tertiary hyperparathyroidism).']],
  ['NP-208', 'ASSOCIATION', 'Renal tumors', 'Chemical-plant worker with a necrotic kidney mass — tumour origin', 'Proximal renal tubules', ['Renal pelvis lining', 'Collecting duct cells', 'Glomeruli'], ['Clear cell renal cell carcinoma arises from the epithelium of the proximal tubule.', 'Exposure to solvents such as trichloroethylene, cadmium and smoking raise the risk.', 'Tumours of the renal pelvis lining are urothelial carcinomas, a different disease.']],
  ['NP-209', 'MECHANISM', 'Renovascular disease', 'Right renal artery clipped — what does the unclipped left kidney do?', 'Excretes more sodium', ['Makes more renin', 'Raises its filtration', 'Retains more water'], ['The clipped kidney senses low pressure and releases renin, raising systemic blood pressure.', 'The normal left kidney sees that high pressure and excretes more sodium (pressure natriuresis).', 'High pressure also suppresses renin release from the left kidney.']],
  ['NP-210', 'SIDE_EFFECT', 'Chronic kidney disease', 'Dialysis patient started on an erythropoiesis-stimulating agent — likely complication', 'Worsening hypertension', ['Hyperkalemia', 'Angioedema', 'Hypoglycemia'], ['Erythropoiesis-stimulating agents raise blood pressure in many dialysis patients.', 'They increase blood viscosity and vessel tone as the red cell mass rises.', 'Blood pressure must be controlled before and during treatment.']],
  ['NP-211', 'ASSOCIATION', 'Water & sodium balance', 'Severely dehydrated climber — where is tubular fluid most dilute?', 'Early distal convoluted tubule', ['Medullary collecting duct', 'Proximal convoluted tubule', 'Descending limb of Henle'], ['The thick ascending limb pumps out salt but cannot absorb water, so fluid leaving it is dilute.', 'That makes the early distal tubule the most dilute part of the nephron in every state.', 'With high ADH, water is then reclaimed in the collecting duct, concentrating the urine.']],
  ['NP-212', 'ASSOCIATION', 'Glomerular disease', 'Edema, hypertension, painful finger joints and a "full house" immunofluorescence pattern', 'Systemic lupus erythematosus', ['Rheumatoid arthritis', 'Granulomatosis with polyangiitis', 'Multiple myeloma'], ['A "full house" pattern means IgG, IgA, IgM, C3 and C1q are all present.', 'It is the hallmark of lupus nephritis.', 'Lupus nephritis is staged by biopsy class, which guides treatment.']],
  ['NP-213', 'ASSOCIATION', 'Tubulointerstitial disease', 'Fever, rash and low urine output a week after ampicillin — affected structure', 'Renal interstitium', ['Glomeruli', 'Small renal arterioles', 'Renal papillae'], ['Drug-induced acute interstitial nephritis is a hypersensitivity reaction in the tissue between the tubules.', 'β-lactam antibiotics are classic triggers, along with NSAIDs, PPIs and diuretics.', 'Stopping the drug usually leads to recovery; steroids may help.']],
  ['NP-214', 'ASSOCIATION', 'Renal physiology', 'Freely filtered substance: fully reabsorbed at low loads, spills into urine once a ceiling is passed', 'Glucose', ['Urea', 'Creatinine', 'Mannitol'], ['Glucose is completely reabsorbed by SGLT transporters in the proximal tubule until they are saturated.', 'Beyond the transport maximum, extra glucose spills into the urine.', 'That is why glycosuria appears when blood glucose exceeds about 180 mg/dL.']],
  ['NP-215', 'ASSOCIATION', 'Cystic kidney disease', 'Newborn with normal kidneys on ultrasound — most likely later kidney disease', 'Autosomal dominant PKD', ['Multicystic dysplastic kidney', 'Autosomal recessive PKD', 'Horseshoe kidney'], ['In autosomal dominant polycystic kidney disease, cysts are present at birth but too small to see.', 'They grow over decades, usually causing symptoms in adulthood.', 'The other options are visible on prenatal or newborn ultrasound.']],
  ['NP-216', 'ASSOCIATION', 'Renovascular disease', 'Young woman dies of a brain bleed; arteries show fibrous webs and aneurysms — additional finding', 'Renal artery stenosis', ['Coarctation of the aorta', 'Adrenal tumor', 'Hypertrophic cardiomyopathy'], ['Alternating webs and dilations ("string of beads") are fibromuscular dysplasia.', 'It most often affects the renal arteries, causing renovascular hypertension in young women.', 'It also affects the carotid and cerebral arteries, which can cause aneurysms and stroke.']],
  ['NP-217', 'ASSOCIATION', 'Renovascular disease', 'Flank pain with wedge-shaped pale areas in the kidney, palpitations and sleep apnea', 'Renal infarction', ['Nephrolithiasis', 'Renal papillary necrosis', 'Pyelonephritis'], ['Sharply outlined, wedge-shaped areas of no flow are infarcts from a blocked artery.', 'The most common source is a clot from the heart, often from atrial fibrillation.', 'Sleep apnea and palpitations point to atrial fibrillation as the cause.']],
  ['NP-218', 'MECHANISM', 'Chronic kidney disease', 'Early CKD with normal phosphate despite falling GFR — what keeps it normal?', 'Raised FGF-23', ['Suppressed parathyroid hormone', 'Low serum magnesium', 'Raised thyrotropin'], ['FGF-23 is released by bone when phosphate starts to build up.', 'It makes the proximal tubule excrete phosphate and lowers calcitriol production.', 'FGF-23 rises very early in CKD, long before phosphate becomes abnormal.']],
  ['NP-219', 'BUZZWORD', 'Glomerular disease', 'Teenager with repeated self-limited gross hematuria during respiratory infections — biopsy', 'Mesangial IgA deposits', ['Linear IgG with crescents', 'Thin basement membrane', 'Granular IgG and C3'], ['IgA nephropathy (Berger disease) causes visible hematuria within a day or two of a mucosal infection.', 'Biopsy shows IgA deposits in the mesangium.', 'It is the most common primary glomerulonephritis worldwide.']],
  ['NP-220', 'ASSOCIATION', 'Acid–base', 'Three days of watery diarrhoea — pH, PaCO₂ and bicarbonate', 'Low pH, low CO₂, low HCO₃⁻', ['High pH, low CO₂, low HCO₃⁻', 'Low pH, high CO₂, normal HCO₃⁻', 'High pH, high CO₂, high HCO₃⁻'], ['Diarrhoea loses bicarbonate from the gut, causing a non-anion gap metabolic acidosis.', 'The lungs compensate by breathing faster, lowering PaCO₂.', 'Chloride rises to replace the lost bicarbonate (hyperchloremic acidosis).']],
  ['NP-221', 'ASSOCIATION', 'Acid–base', 'Infant with polyuria, rickets and low bicarbonate from proximal RTA — chloride, glucose, phosphate', 'High chloride, normal glucose, low phosphate', ['Low chloride, normal glucose, low phosphate', 'High chloride, high glucose, low phosphate', 'Normal chloride, high glucose, normal phosphate'], ['Proximal tubule failure (Fanconi syndrome) wastes bicarbonate, phosphate, glucose and amino acids.', 'Chloride rises to replace lost bicarbonate, and phosphate loss causes rickets.', 'Blood glucose stays normal; it is only the urine that contains glucose.']],
  ['NP-222', 'ASSOCIATION', 'Renovascular disease', 'Creatinine jumps after an ACE inhibitor in bilateral renal artery stenosis — repeat urinalysis', 'No protein, cells or casts', ['Protein 2+, red cell casts', 'Protein 4+, oval fat bodies', 'White cell casts, eosinophils'], ['Renal artery stenosis reduces blood flow but leaves the glomeruli and tubules intact.', 'So the urine stays bland, with no protein, cells or casts.', 'An ACE inhibitor lowers glomerular pressure further, which is why creatinine rose.']],
  ['NP-223', 'ASSOCIATION', 'Pharmacology', 'After surgery, a drug causes flushing, sweating, nausea, slow pulse and small pupils — indication', 'Atonic bladder', ['Urinary obstruction', 'Hypovolemic shock', 'Fluid overload'], ['These are cholinergic effects, typical of a muscarinic agonist such as bethanechol.', 'Bethanechol is used to make a weak (atonic) bladder contract after surgery.', 'It must not be used if retention is caused by an obstruction.']],
  ['NP-224', 'ASSOCIATION', 'Electrolytes', 'Hyperemesis gravidarum — sodium, potassium, chloride, bicarbonate', 'Low, low, low, high', ['Low, low, low, low', 'Normal, high, normal, low', 'High, normal, high, normal'], ['Vomiting loses hydrochloric acid, so chloride falls and bicarbonate rises: metabolic alkalosis.', 'Volume loss raises aldosterone, which makes the kidneys waste potassium.', 'Treatment is saline with potassium; urine chloride is low.']],
  ['NP-225', 'ASSOCIATION', 'Acute kidney injury', 'Ischemic acute tubular necrosis after trauma — biopsy one month later', 'Tubular re-epithelialization', ['Diffuse mesangial sclerosis', 'Segmental glomerulosclerosis', 'Medullary scarring'], ['Tubular cells can regenerate as long as the basement membrane is intact.', 'Over weeks, surviving cells divide and reline the tubules (re-epithelialization).', 'This is why most patients with acute tubular necrosis recover kidney function.']],
  ['NP-226', 'ASSOCIATION', 'Chronic kidney disease', 'Advanced CKD with subperiosteal resorption on hand X-ray — bone biopsy', 'More osteoclasts, more osteoblasts', ['Fewer osteoclasts, more osteoblasts', 'Fewer osteoclasts, fewer osteoblasts', 'Normal osteoclasts and osteoblasts'], ['Secondary hyperparathyroidism in CKD causes high bone turnover: osteitis fibrosa cystica.', 'PTH activates osteoclasts, and osteoblasts increase as the bone tries to repair.', 'The bone is replaced with fibrous tissue and becomes weak.']],
  ['NP-227', 'ASSOCIATION', 'Kidney stones', 'Recurrent colicky flank pain with a dilated ureter — urinalysis', 'Red blood cells', ['Red blood cell casts', 'White blood cell casts', 'Malignant cells'], ['A stone scrapes the ureter lining, releasing free red blood cells into the urine.', 'Red cell casts form only in the tubules, so they mean glomerular disease, not stones.', 'Most patients with a ureteric stone have blood in the urine.']],
  ['NP-228', 'ASSOCIATION', 'Acid–base', 'Teenager with sudden confusion, fever, fast breathing and a high anion gap', 'Aspirin intoxication', ['Diabetic ketoacidosis', 'Ethanol intoxication', 'Carbon monoxide poisoning'], ['Salicylates stimulate breathing directly and also cause an anion gap acidosis.', 'Uncoupling of oxidative phosphorylation produces heat, so fever is common.', 'Tinnitus is a classic clue; treat with bicarbonate and dialysis if severe.']],
  ['NP-229', 'ASSOCIATION', 'Diabetic & hypertensive kidney', 'Uremic itching; biopsy shows glassy pink thickening of small artery walls — condition', 'Diabetes mellitus', ['Malignant hypertension', 'Atheroembolic renal disease', 'Multiple myeloma'], ['Glassy pink thickening of arteriole walls is hyaline arteriolosclerosis.', 'It occurs with diabetes and benign hypertension, and in diabetes it affects both arterioles.', 'Malignant hypertension gives onion-skin (hyperplastic) changes instead.']],
  ['NP-230', 'ASSOCIATION', 'Tubulointerstitial disease', 'Years of daily painkillers; small, irregular kidneys with calcified papillae', 'Chronic interstitial nephritis', ['Renal artery stenosis', 'Focal segmental glomerulosclerosis', 'Chronic pyelonephritis'], ['Long-term analgesic use damages the interstitium and papillae (analgesic nephropathy).', 'Papillary necrosis and scarring leave small, irregular kidneys with calcified tips.', 'It also raises the risk of urothelial cancer.']],
  ['NP-231', 'MECHANISM', 'Electrolytes', 'Malnourished alcoholic given dextrose fluids, then phosphate crashes — cause', 'Phosphate shifting into cells', ['Less proximal phosphate reabsorption', 'More bone phosphate uptake', 'More colonic phosphate loss'], ['Glucose triggers insulin, which drives phosphate into liver and muscle cells to make ATP.', 'Malnourished patients have little stored phosphate, so blood levels crash: refeeding syndrome.', 'Low phosphate can cause weakness, heart failure and respiratory failure.']],
  ['NP-232', 'MECHANISM', 'Renovascular disease', 'Child with bloody diarrhoea, then anemia, low platelets and kidney failure — mechanism', 'Microthrombi in small vessels', ['IgA-mediated vasculitis', 'Widespread coagulation activation', 'Medium-artery vasculitis'], ['Shiga toxin from E. coli O157:H7 damages endothelium, causing hemolytic uremic syndrome.', 'Platelet clots form in small kidney vessels and shear red cells (schistocytes).', 'Unlike DIC, clotting times (PT and PTT) stay normal.']],
  ['NP-233', 'SIDE_EFFECT', 'Acute kidney injury', 'Kidney injury after a week of gentamicin — histology', 'Focal tubular epithelial necrosis', ['Leukocytes in the interstitium', 'Collagen replacing glomeruli', 'Normal renal architecture'], ['Aminoglycosides are taken up by proximal tubule cells and are directly toxic to them.', 'This causes acute tubular necrosis, usually non-oliguric, after 5–7 days.', 'Risk rises with high trough levels, older age and other nephrotoxins.']],
  ['NP-234', 'MECHANISM', 'Glomerular disease', 'Prolonged fever, a new murmur and hematuria with red cell casts — kidney mechanism', 'Circulating immune complexes', ['Endotoxin tubular injury', 'Anti-GBM antibodies', 'Metastatic infection focus'], ['Infective endocarditis keeps releasing bacterial antigens into the blood.', 'Antibodies form immune complexes that lodge in the glomeruli, causing glomerulonephritis with low complement.', 'Septic emboli can also cause kidney infarcts or abscesses.']],
  ['NP-235', 'ASSOCIATION', 'Obstruction & urinary tract', 'Bilateral hydronephrosis a year after prostate radiotherapy — cause', 'Fibrosis', ['Mucosal hyperplasia', 'Radiation mucositis', 'Granuloma formation'], ['Radiation damages small vessels, and over months the tissue scars.', 'Scarring of the urethra or bladder neck narrows the outflow (stricture).', 'Urine backs up into both ureters and kidneys, causing obstructive uropathy.']],
  ['NP-236', 'MECHANISM', 'Acid–base', 'Sjögren syndrome with low potassium and non-anion gap acidosis — mechanism', 'Impaired distal acid secretion', ['Distal aldosterone resistance', 'More proximal HCO₃⁻ reabsorption', 'More endogenous acid production'], ['Type 1 (distal) RTA means the distal nephron cannot secrete hydrogen ions, so urine pH stays above 5.5.', 'Autoimmune diseases such as Sjögren syndrome are common causes.', 'It causes low potassium and calcium phosphate kidney stones.']],
];
